    ) public returns (AttrState.Mutation memory) {
        (
            ,
            T.Binding memory b,
            T.Attestation memory p,
            bytes32 operativeIdentityHash,
            R.AuthorityFact memory authority,
            address signer,
            uint256 nonce,
            uint64 signedAt,
