pragma solidity ^0.8.19;
import "./StreamArtistConsentState.sol";
import "./StreamArtistContentHashes.sol";
import "../../interfaces/stream/artist/IStreamArtistContentOwner.sol";

/// @notice Fixed decoding of original Consent writer calls after their host authority checks.
/// @dev No ledger, signature or receipt policy is introduced; fixed state workers remain authoritative.
library StreamArtistConsentTransport {
    function saleEncoded(
        mapping(bytes32 => Sale.Record) storage records,
        mapping(bytes32 => bytes32) storage latest,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistConsentState.Context memory o,
        bytes calldata encoded,
        uint8 principalClass
    ) public returns (StreamArtistConsentState.Mutation memory) {
        (, T.Binding memory b, Sale.Consent memory p, address signer, uint256 nonce) =
            abi.decode(encoded[4:], (T.ActionContext, T.Binding, Sale.Consent, address, uint256));
        return StreamArtistConsentState.saleConsentForAuthority(
            records, latest, replay, o, b, p, signer, principalClass, nonce
        );
    }

    event ArtistConsentDelegationRecorded(
        uint16 schemaVersion,
        bytes32 indexed recordHash,
        bytes32 indexed delegationRecordHash,
        bytes32 indexed artistId,
        uint16 operationId
    );

    function noteDelegation(
        mapping(bytes32 => bytes32) storage delegations,
        StreamArtistConsentState.Mutation memory m,
        bytes32 grant,
        bytes32 artistId,
        uint16 operation
    ) public returns (StreamArtistConsentState.Mutation memory) {
        if (grant == 0 || delegations[m.record] != 0) revert T.InvalidRecord();
        delegations[m.record] = grant;
        m.action = keccak256(abi.encode(m.action, grant));
        m.state = keccak256(abi.encode(m.state, grant));
        emit ArtistConsentDelegationRecorded(1, m.record, grant, artistId, operation);
        return m;
    }

    function policyEncoded(
        mapping(bytes32 => bytes32) storage records,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistConsentState.Context memory o,
        bytes calldata encoded,
        uint8 principalClass
    ) public returns (StreamArtistConsentState.Mutation memory) {
        (, T.Binding memory b, T.PolicyConsent memory p, address signer, uint256 nonce) =
            abi.decode(encoded[4:], (T.ActionContext, T.Binding, T.PolicyConsent, address, uint256));
        return StreamArtistConsentState.policyForAuthority(
            records, replay, o, b, p, signer, principalClass, nonce
        );
    }

    function economicsEncoded(
        mapping(bytes32 => bytes32) storage records,
        mapping(bytes32 => bytes32) storage delegations,
        mapping(bytes32 => T.ReplayCell) storage replay,
        mapping(bytes32 => EconomicsEvidence.Association) storage associations,
        mapping(bytes32 => bytes32) storage associatedRecords,
        StreamArtistConsentState.Context memory o,
        bytes calldata encoded,
        uint8 principalClass,
        bytes32 grant
    ) public returns (StreamArtistConsentState.Mutation memory) {
        (
            ,
            T.Binding memory b,
            T.EconomicsConsent memory p,
            T.Payout memory designation,
            address signer,
            uint256 nonce
        ) = abi.decode(
            encoded[4:],
            (T.ActionContext, T.Binding, T.EconomicsConsent, T.Payout, address, uint256)
        );
        return StreamArtistConsentState.economicsAssociatedForAuthority(
            records,
            delegations,
            replay,
            associations,
            associatedRecords,
            o,
            b,
            p,
            designation,
            signer,
            principalClass,
            nonce,
            grant
        );
    }

    function ratificationEncoded(
        mapping(uint256 => T.RatificationRecord) storage records,
        mapping(bytes32 => T.RatificationRecord) storage history,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistConsentState.Context memory o,
        bytes calldata encoded,
        uint8 principalClass
    ) public returns (StreamArtistConsentState.Mutation memory) {
        (, T.Binding memory b, T.Ratification memory p, address signer, uint256 nonce) =
            abi.decode(encoded[4:], (T.ActionContext, T.Binding, T.Ratification, address, uint256));
        return StreamArtistConsentState.ratificationForAuthority(
            records, history, replay, o, b, p, signer, principalClass, nonce
        );
    }

    event ArtistContentConsentRecorded(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        bytes32 indexed familyId,
        address indexed signer,
        bytes32 newStateHash,
        uint8 authorityClass,
        uint256 nonce,
        uint64 signedAt,
        bytes32 consentRecordHash
    );
    event ArtistContentRecordContext(
        uint16 schemaVersion, bytes32 indexed recordHash, address metadataContract, bytes32 artistId
    );

    function contentConsentEncoded(
        mapping(bytes32 => IStreamArtistContentRecordsOwner.ConsentRecord) storage records,
        mapping(bytes32 => bytes32) storage latest,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistConsentState.Context memory o,
        bytes calldata encoded,
        uint8 authorityClass
    ) public returns (StreamArtistConsentState.Mutation memory m) {
        (, T.Binding memory b, Content.Consent memory p, address signer, uint256 nonce) =
            abi.decode(encoded[4:], (T.ActionContext, T.Binding, Content.Consent, address, uint256));
        m.record = StreamArtistContentHashes.consentRecord(
            o.environment, p, b.artistId, signer, authorityClass, nonce, o.observedAt
        );
        bytes32 scope = keccak256(abi.encode(p, b.generation));
        bytes32 key = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_OWNER_REPLAY_KEY_V2"),
                o.environment.chainId,
                o.environment.registry,
                o.coordinator,
                o.archive,
                address(this),
                o.domain,
                keccak256("consent_finality.replay.content_consent_key"),
                keccak256(abi.encode(scope, m.record))
            )
        );
        if (replay[key].status != 0) revert T.Replay(key);
        replay[key] = T.ReplayCell(m.record, o.revision + 1, 1, 2);
        StreamArtistAuthorityCheckpoint.noteReplay(key, replay[key]);
        IStreamArtistContentRecordsOwner.ConsentRecord memory item =
            IStreamArtistContentRecordsOwner.ConsentRecord(
                m.record, b.artistId, b.generation, p, authorityClass
            );
        records[m.record] = item;
        latest[scope] = m.record;
        m.action = keccak256(abi.encode(b, p, signer, nonce));
        m.state = keccak256(abi.encode(scope, item));
        m.replay = keccak256(abi.encode(key, m.record));
    }

    /// @dev Called only after the host's original commit and native receipt append.
    function emitContentConsentEncoded(
        bytes calldata encoded,
        bytes32 record,
        uint8 authorityClass,
        uint64 observedAt
    ) public {
        (, T.Binding memory b, Content.Consent memory p, address signer, uint256 nonce) = abi.decode(
            encoded[4:], (T.ActionContext, T.Binding, Content.Consent, address, uint256)
        );
        emit ArtistContentConsentRecorded(
            1,
            p.collectionId,
            p.familyId,
            signer,
            p.newStateHash,
            authorityClass,
            nonce,
            observedAt,
            record
        );
        emit ArtistContentRecordContext(1, record, p.metadataContract, b.artistId);
    }

    event ArtistContentFreezeAuthorized(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        address indexed signer,
        bytes32[] lockClasses,
        bytes32 expectedStateHash,
        uint8 authorityClass,
        uint256 nonce,
        uint64 signedAt,
        bytes32 freezeRecordHash
    );

    function contentFreezeEncoded(
        mapping(bytes32 => Content.FreezeRecord) storage records,
        mapping(bytes32 => bytes32) storage latest,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistConsentState.Context memory o,
        bytes calldata encoded,
        uint8 authorityClass
    ) public returns (StreamArtistConsentState.Mutation memory m) {
        (, T.Binding memory b, Content.Freeze memory p, address signer, uint256 nonce) =
            abi.decode(encoded[4:], (T.ActionContext, T.Binding, Content.Freeze, address, uint256));
        m.record = StreamArtistContentHashes.freezeRecord(
            o.environment, p, b.artistId, signer, authorityClass, nonce, o.observedAt
        );
        bytes32 key = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_OWNER_REPLAY_KEY_V2"),
                o.environment.chainId,
                o.environment.registry,
                o.coordinator,
                o.archive,
                address(this),
                o.domain,
                keccak256("consent_finality.replay.freeze_key"),
                keccak256(abi.encode(keccak256("CONTENT"), p.collectionId, b.generation, m.record))
            )
        );
        if (replay[key].status != 0) revert T.Replay(key);
        replay[key] = T.ReplayCell(m.record, o.revision + 1, 1, 2);
        StreamArtistAuthorityCheckpoint.noteReplay(key, replay[key]);
        Content.FreezeRecord memory item = Content.FreezeRecord(
            m.record,
            b.artistId,
            b.generation,
            p.metadataContract,
            p.lockClasses,
            p.expectedStateHash,
            authorityClass
        );
        records[m.record] = item;
        for (uint256 i; i < p.lockClasses.length; ++i) {
            latest[
                keccak256(
                    abi.encode(p.collectionId, b.generation, p.metadataContract, p.lockClasses[i])
                )
            ] = m.record;
        }
        m.action = keccak256(abi.encode(b, p, signer, nonce));
        m.state = keccak256(abi.encode(p.collectionId, item));
        m.replay = keccak256(abi.encode(key, m.record));
    }

    /// @dev Called only after the host's original commit and native receipt append.
    function emitContentFreezeEncoded(
        bytes calldata encoded,
        bytes32 record,
        uint8 authorityClass,
        uint64 observedAt
    ) public {
        (, T.Binding memory b, Content.Freeze memory p, address signer, uint256 nonce) = abi.decode(
            encoded[4:], (T.ActionContext, T.Binding, Content.Freeze, address, uint256)
        );
        emit ArtistContentFreezeAuthorized(
            1,
            p.collectionId,
            signer,
            p.lockClasses,
            p.expectedStateHash,
            authorityClass,
            nonce,
            observedAt,
            record
        );
        emit ArtistContentRecordContext(1, record, p.metadataContract, b.artistId);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import { StreamArtistConsentTransport } from "./StreamArtistConsentTransport.sol";
import "../../interfaces/stream/artist/IStreamArtistSanctionConfirmation.sol";
import "./StreamArtistConsentStorage.sol";
import "./StreamArtistSanctionConfirmationState.sol";

/// @notice Fixed implementation of the Consent owner's explicit mutations.
/// @dev All semantic callbacks reject direct calls before reading authority or snapshots.
contract StreamArtistConsentWriterExtension is StreamArtistConsentStorage {
    error ExtensionWrongHost(address actual);
    address private immutable _host;

    constructor(
        address host_,
        address registry_,
        address coordinator_,
        address archive_,
        address core_,
        address manager_
    ) StreamArtistConsentStorage(registry_, coordinator_, archive_, core_, manager_) {
        if (host_ == address(0) || host_ == address(this)) revert T.InvalidBinding();
        _host = host_;
    }
    modifier onlyHost() {
        if (address(this) != _host) revert ExtensionWrongHost(address(this));
        _;
    }

    function recordRecoveryApproval(
        T.ActionContext calldata c,
        T.Binding calldata b,
        Recovery.ApprovalRecord calldata r,
        R.AuthorityFact calldata authority,
        Approval.Admission calldata admission
    ) external onlyHost returns (bytes32) {
        _check(c, 22);
        StreamArtistRecoveryApprovalState.Mutation memory m =
            StreamArtistRecoveryApprovalState.recordEncoded(
                _recoveryApprovals,
                _replay,
                StreamArtistRecoveryApprovalState.OwnerContext(
                    _environment(), operationCoordinator, archiveV2, domainId, _revision, _now()
                ),
                msg.data
            );
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(c.operationId, m.record, b.artistId, r.terms.collectionId);
        return m.record;
    }

    function consumeSanctionFinalization(
        T.ActionContext calldata c,
        T.Binding calldata b,
        Confirmation.Transition calldata p
    ) external onlyHost returns (bytes32 replayKey) {
        _check(c, 13);
        StreamArtistConsentState.Mutation memory m;
        (m, replayKey) = StreamArtistSanctionConfirmationState.consumeEncoded(
            _sanctions,
            _replay,
            StreamArtistConsentState.Context(
                _environment(), operationCoordinator, archiveV2, domainId, _revision, 0
            ),
            msg.data
        );
        _commit(c, m.action, m.state, m.replay, m.record);
    }

    function recordSanction(
        T.ActionContext calldata c,
        T.Binding calldata b,
        S.Record calldata r,
        R.AuthorityFact calldata authority,
        address finalityRegistry,
        bytes calldata ceremony,
        bytes calldata signature
    ) external onlyHost returns (bytes32) {
        _check(c, 12);
        StreamArtistConsentState.Mutation memory m = StreamArtistSanctionState.recordEncoded(
            _sanctions, _replay, _consentContext(), msg.data
        );
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(c.operationId, m.record, b.artistId, r.terms.collectionId);
        return m.record;
    }

    function recordSaleConsent(
        T.ActionContext calldata c,
        T.Binding calldata b,
        Sale.Consent calldata p,
        address signer,
        uint256 nonce,
        R.AuthorityFact calldata authority
    ) external onlyHost returns (bytes32 record) {
        _check(c, 16);
        StreamArtistCurrentAuthorityFacts.requireAccepted(b, signer, authority, false);
        StreamArtistConsentState.Mutation memory m = StreamArtistConsentTransport.saleEncoded(
            _saleRecords,
            _latestSaleConsents,
            _replay,
            _consentContext(),
            msg.data,
            authority.authorityClass
        );
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(c.operationId, m.record, b.artistId, p.collectionId);
        return m.record;
    }

    function recordPolicy(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.PolicyConsent calldata p,
        address signer,
        uint256 nonce
    ) external onlyHost returns (bytes32 record) {
        return _currentRecordPolicy(
            c, b, p, signer, nonce, R.AuthorityFact(b.artistId, b.artistAddress, 1, 1)
        );
    }

    function recordPolicyWithAuthority(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.PolicyConsent calldata p,
        address signer,
        uint256 nonce,
        R.AuthorityFact calldata authority
    ) external onlyHost returns (bytes32 record) {
        return _currentRecordPolicy(c, b, p, signer, nonce, authority);
    }

    function recordEconomics(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.EconomicsConsent calldata p,
        T.Payout calldata designation,
        address signer,
        uint256 nonce
    ) external onlyHost returns (bytes32 record) {
        return _currentRecordEconomics(
            c, b, p, designation, signer, nonce, R.AuthorityFact(b.artistId, b.artistAddress, 1, 1)
        );
    }

    function recordEconomicsWithAuthority(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.EconomicsConsent calldata p,
        T.Payout calldata designation,
        address signer,
        uint256 nonce,
        R.AuthorityFact calldata authority
    ) external onlyHost returns (bytes32 record) {
        return _currentRecordEconomics(c, b, p, designation, signer, nonce, authority);
    }

    function recordDelegatedPolicyConsent(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.PolicyConsent calldata p,
        address signer,
        uint256 nonce,
        bytes32 grant
    ) external onlyHost returns (bytes32) {
        _check(c, 14);
        _requireDelegated(b, signer, grant);
        if (b.consentMode != 2) revert T.InvalidRecord();
        StreamArtistConsentState.Mutation memory m = StreamArtistConsentTransport.policyEncoded(
            _policies, _replay, _consentContext(), msg.data, 2
        );
        m = StreamArtistConsentTransport.noteDelegation(
            _recordDelegation, m, grant, b.artistId, c.operationId
        );
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(c.operationId, m.record, b.artistId, p.collectionId);
        return m.record;
    }

    function recordDelegatedSaleConsent(
        T.ActionContext calldata c,
        T.Binding calldata b,
        Sale.Consent calldata p,
        address signer,
        uint256 nonce,
        bytes32 grant
    ) external onlyHost returns (bytes32) {
        _check(c, 16);
        _requireDelegated(b, signer, grant);
        if (b.consentMode != 2) revert T.InvalidRecord();
        StreamArtistConsentState.Mutation memory m = StreamArtistConsentTransport.saleEncoded(
            _saleRecords, _latestSaleConsents, _replay, _consentContext(), msg.data, 2
        );
        m = StreamArtistConsentTransport.noteDelegation(
            _recordDelegation, m, grant, b.artistId, c.operationId
        );
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(c.operationId, m.record, b.artistId, p.collectionId);
        return m.record;
    }

    function recordDelegatedEconomics(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.EconomicsConsent calldata p,
        T.Payout calldata designation,
        address signer,
        uint256 nonce,
        bytes32 grant
    ) external onlyHost returns (bytes32) {
        _check(c, 15);
        _requireDelegated(b, signer, grant);
        return _recordEconomics(c, b, p, designation, signer, nonce, grant, 2);
    }

    function recordRatification(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.Ratification calldata p,
        address signer,
        uint256 nonce
    ) external onlyHost returns (bytes32 record) {
        return _currentRecordRatification(
            c, b, p, signer, nonce, R.AuthorityFact(b.artistId, b.artistAddress, 1, 1)
        );
    }

    function recordRatificationWithAuthority(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.Ratification calldata p,
        address signer,
        uint256 nonce,
        R.AuthorityFact calldata authority
    ) external onlyHost returns (bytes32 record) {
        return _currentRecordRatification(c, b, p, signer, nonce, authority);
    }

    function authorizeRoyaltyFreeze(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.RoyaltyFreeze calldata p,
        address signer,
        uint256 nonce
    ) external onlyHost returns (bytes32 record) {
        return _currentAuthorizeRoyaltyFreeze(
            c, b, p, signer, nonce, R.AuthorityFact(b.artistId, b.artistAddress, 1, 1)
        );
    }

    function authorizeRoyaltyFreezeWithAuthority(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.RoyaltyFreeze calldata p,
        address signer,
        uint256 nonce,
        R.AuthorityFact calldata authority
    ) external onlyHost returns (bytes32 record) {
        return _currentAuthorizeRoyaltyFreeze(c, b, p, signer, nonce, authority);
    }

    function authorizeDelegatedRoyaltyFreeze(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.RoyaltyFreeze calldata p,
        address signer,
        uint256 nonce,
        bytes32 grant
    ) external onlyHost returns (bytes32) {
        _check(c, 20);
        _requireDelegated(b, signer, grant);
        return _authorizeRoyaltyFreeze(c, b, p, signer, nonce, grant, 2);
    }

    function recordContentConsent(
        T.ActionContext calldata c,
        T.Binding calldata b,
        Content.Consent calldata p,
        address signer,
        uint256 nonce
    ) external onlyHost returns (bytes32 record) {
        return _currentRecordContentConsent(
            c, b, p, signer, nonce, R.AuthorityFact(b.artistId, b.artistAddress, 1, 1)
        );
    }

    function recordContentConsentWithAuthority(
        T.ActionContext calldata c,
        T.Binding calldata b,
        Content.Consent calldata p,
        address signer,
        uint256 nonce,
        R.AuthorityFact calldata authority
    ) external onlyHost returns (bytes32 record) {
        return _currentRecordContentConsent(c, b, p, signer, nonce, authority);
    }

    function authorizeContentFreeze(
        T.ActionContext calldata c,
        T.Binding calldata b,
        Content.Freeze calldata p,
        address signer,
        uint256 nonce
    ) external onlyHost returns (bytes32 record) {
        return _currentAuthorizeContentFreeze(
            c, b, p, signer, nonce, R.AuthorityFact(b.artistId, b.artistAddress, 1, 1)
        );
    }

    function authorizeContentFreezeWithAuthority(
        T.ActionContext calldata c,
        T.Binding calldata b,
        Content.Freeze calldata p,
        address signer,
        uint256 nonce,
        R.AuthorityFact calldata authority
    ) external onlyHost returns (bytes32 record) {
        return _currentAuthorizeContentFreeze(c, b, p, signer, nonce, authority);
    }

    function _currentRecordPolicy(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.PolicyConsent calldata p,
        address signer,
        uint256 nonce,
        R.AuthorityFact memory authority
    ) private returns (bytes32 record) {
        _check(c, 14);
        StreamArtistCurrentAuthorityFacts.requireAccepted(b, signer, authority, false);
        StreamArtistConsentState.Mutation memory m = StreamArtistConsentTransport.policyEncoded(
            _policies, _replay, _consentContext(), msg.data, authority.authorityClass
        );
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(c.operationId, m.record, b.artistId, p.collectionId);
        return m.record;
    }

    function _currentRecordEconomics(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.EconomicsConsent calldata p,
        T.Payout calldata designation,
        address signer,
        uint256 nonce,
        R.AuthorityFact memory authority
    ) private returns (bytes32 record) {
        _check(c, 15);
        StreamArtistCurrentAuthorityFacts.requireAccepted(b, signer, authority, false);
        return _recordEconomics(
            c, b, p, designation, signer, nonce, bytes32(0), authority.authorityClass
        );
    }

    function _recordEconomics(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.EconomicsConsent calldata p,
        T.Payout calldata designation,
        address signer,
        uint256 nonce,
        bytes32 grant,
        uint8 principalClass
    ) private returns (bytes32 record) {
        StreamArtistConsentState.Mutation memory m =
            StreamArtistConsentTransport.economicsEncoded(
                _economics,
                _recordDelegation,
                _replay,
                _economicsAssociations,
                _associatedEconomicsRecords,
                _consentContext(),
                msg.data,
                principalClass,
                grant
            );
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(c.operationId, m.record, b.artistId, p.collectionId);
        return m.record;
    }

    function _currentRecordRatification(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.Ratification calldata p,
        address signer,
        uint256 nonce,
        R.AuthorityFact memory authority
    ) private returns (bytes32 record) {
        _check(c, 52);
        StreamArtistCurrentAuthorityFacts.requireAccepted(b, signer, authority, false);
        StreamArtistConsentState.Mutation memory m = StreamArtistConsentTransport.ratificationEncoded(
            _ratifications,
            _ratificationRecords,
            _replay,
            _consentContext(),
            msg.data,
            authority.authorityClass
        );
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(c.operationId, m.record, b.artistId, p.collectionId);
        return m.record;
    }

    function _currentAuthorizeRoyaltyFreeze(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.RoyaltyFreeze calldata p,
        address signer,
        uint256 nonce,
        R.AuthorityFact memory authority
    ) private returns (bytes32 record) {
        _check(c, 20);
        StreamArtistCurrentAuthorityFacts.requireAccepted(b, signer, authority, true);
        return _authorizeRoyaltyFreeze(c, b, p, signer, nonce, bytes32(0), authority.authorityClass);
    }

    function _authorizeRoyaltyFreeze(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.RoyaltyFreeze calldata p,
        address signer,
        uint256 nonce,
        bytes32 grant,
        uint8 principalClass
    ) private returns (bytes32 record) {
        if (
            p.resolver == address(0) || p.collectionId == 0
                || p.revenueClass != keccak256("ROYALTY_ERC2981")
                || p.expectedAssignmentHash == bytes32(0)
        ) {
            revert T.InvalidRecord();
        }
        uint8 authorityClass = grant == bytes32(0) ? principalClass : 2;
        record = StreamArtistEconomicsHashes.royaltyFreezeRecordForAuthority(
            _environment(), p, b.artistId, signer, authorityClass, nonce, _now()
        );
        bytes32 scope = keccak256(abi.encode(p, b.artistId, b.generation));
        bytes32 key = _consume(keccak256("consent_finality.replay.freeze_key"), scope, record);
        T.RoyaltyFreezeRecord memory authorization =
            T.RoyaltyFreezeRecord(record, b.artistId, b.generation);
        _royaltyFreezes[scope] = authorization;
        if (grant != bytes32(0)) _recordDelegation[record] = grant;
        _commit(
            c,
            grant == bytes32(0)
                ? keccak256(abi.encode(b, p, signer, nonce))
                : keccak256(abi.encode(b, p, signer, nonce, grant)),
            grant == bytes32(0)
                ? keccak256(abi.encode(scope, authorization))
                : keccak256(abi.encode(scope, authorization, grant)),
            keccak256(abi.encode(key, record)),
            record
        );
        _native(c.operationId, record, b.artistId, p.collectionId);
        emit ArtistRoyaltyFreezeAuthorized(
            1,
            p.collectionId,
            p.expectedAssignmentHash,
            signer,
            authorityClass,
            nonce,
            _now(),
            record
        );
        if (grant != bytes32(0)) {
            emit ArtistRecordDelegation(1, record, grant, b.artistId, p.resolver, p.revenueClass, 2);
        }
    }

    function _currentRecordContentConsent(
        T.ActionContext calldata c,
        T.Binding calldata b,
        Content.Consent calldata p,
        address signer,
        uint256 nonce,
        R.AuthorityFact memory authority
    ) private returns (bytes32 record) {
        _check(c, 17);
        StreamArtistCurrentAuthorityFacts.requireAccepted(b, signer, authority, false);
        StreamArtistContentHashes.validateConsent(p);
        StreamArtistConsentState.Mutation memory m =
            StreamArtistConsentTransport.contentConsentEncoded(
                _contentConsents,
                _latestContentConsent,
                _replay,
                _consentContext(),
                msg.data,
                authority.authorityClass
            );
        record = m.record;
        _commit(c, m.action, m.state, m.replay, record);
        _native(c.operationId, record, b.artistId, p.collectionId);
        StreamArtistConsentTransport.emitContentConsentEncoded(
            msg.data, record, authority.authorityClass, _now()
        );
    }

    function _currentAuthorizeContentFreeze(
        T.ActionContext calldata c,
        T.Binding calldata b,
        Content.Freeze calldata p,
        address signer,
        uint256 nonce,
        R.AuthorityFact memory authority
    ) private returns (bytes32 record) {
        _check(c, 21);
        StreamArtistCurrentAuthorityFacts.requireAccepted(b, signer, authority, true);
        StreamArtistContentHashes.validateFreeze(p);
        StreamArtistConsentState.Mutation memory m =
            StreamArtistConsentTransport.contentFreezeEncoded(
                _contentFreezes,
                _latestContentFreeze,
                _replay,
                _consentContext(),
                msg.data,
                authority.authorityClass
            );
        record = m.record;
        _commit(c, m.action, m.state, m.replay, record);
        _native(c.operationId, record, b.artistId, p.collectionId);
        StreamArtistConsentTransport.emitContentFreezeEncoded(
            msg.data, record, authority.authorityClass, _now()
        );
    }

    function _consentContext() private view returns (StreamArtistConsentState.Context memory) {
        return StreamArtistConsentState.Context(
            _environment(), operationCoordinator, archiveV2, domainId, _revision, _now()
        );
    }

    function _requireDelegated(T.Binding calldata b, address signer, bytes32 grant) private pure {
        if (
            !b.accepted || (b.consentMode != 1 && b.consentMode != 2) || b.artistId == bytes32(0)
                || signer == address(0) || grant == bytes32(0)
        ) revert T.InvalidRecord();
    }

    function _requireAccepted(T.Binding calldata b, address signer) private pure {
        if (
            !b.accepted || (b.consentMode != 1 && b.consentMode != 2) || b.artistId == bytes32(0)
                || signer != b.artistAddress
        ) revert T.InvalidRecord();
    }
}

