    ) internal pure {
        if (
            artistId == bytes32(0) || a.artistId != artistId || signer == address(0)
                || a.authorityAddress != signer
                || !StreamArtistAuthorityPolicy.ordinary(a.authorityClass, a.status, defensive)
        ) revert T.InvalidRecord();
    }
}

