            )
        );
        return StreamArtistHashes.typed(e, body);
    }

    function record(
        StreamArtistHashes.Environment memory e,
        Estate.Request memory p,
        uint256 nonce,
        uint64 requestedAt,
        uint64 noticeEndsAt
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ESTATE_ACTIVATION_RECORD_V1"),
                e.chainId,
                e.registry,
                p.artistId,
                p.successor,
                p.evidenceHash,
                nonce,
                requestedAt,
                noticeEndsAt
            )
        );
    }
}

