pragma solidity ^0.8.19;
import { StreamArtistRecoveredTimingInventory } from "./StreamArtistRecoveredTimingInventory.sol";
import {
    StreamArtistRecoveredTimingTypes
} from "../../interfaces/stream/artist/StreamArtistRecoveredTimingTypes.sol";

import "./StreamArtistEstateState.sol";
import "./StreamArtistTimingState.sol";

/// @notice Estate notice configuration shares the canonical timing context, with its own revision.
library StreamArtistEstateTiming {
    event ArtistWindowChanged(
        uint16 schemaVersion,
        bytes32 indexed parameter,
        uint64 oldValue,
        uint64 newValue,
        uint64 floor,
        uint64 revision,
        bytes32 indexed actionId
    );

    function configure(
        StreamArtistEstateState.State storage s,
        address executor,
        address actor,
        uint64 value,
        uint64 expectedRevision
    ) public {
        bytes32 parameter = keccak256("ARTIST_ESTATE_ACTIVATION_NOTICE_SECONDS");
        if (actor != executor || executor == address(0)) revert T.Unauthorized(actor);
        (uint64 prior, uint64 floor, uint64 revision) = StreamArtistEstateState.timing(s);
        if (
            revision != expectedRevision || revision == type(uint64).max || value == prior
                || value < floor || block.timestamp > type(uint64).max
                || uint256(value) + block.timestamp > type(uint64).max
        ) {
            revert R.InvalidArtistWindow(parameter);
        }
        (
            bool executing,
            bytes32 actionId,
            uint8 actionClass,
            bytes32 scope,
            bytes32 oldHash,
            bytes32 newHash
        ) = IStreamGovernedParameterAuthority(executor).currentAction();
        if (
            !executing || actionId == bytes32(0)
                || (value < prior ? actionClass != 1 : actionClass > 1)
                || scope != StreamArtistTimingState.scope(parameter)
                || oldHash != StreamArtistTimingState.stateHash(parameter, prior, floor, revision)
                || newHash
                    != StreamArtistTimingState.stateHash(parameter, value, floor, revision + 1)
        ) {
            revert R.InvalidArtistWindowContext();
        }
        bytes32 key = keccak256(abi.encode(actionId, parameter, oldHash, newHash));
        if (s.timingActions[key]) revert R.InvalidArtistWindowContext();
        s.timingActions[key] = true;
        s.noticeSeconds = value;
        s.noticeRevision = revision + 1;
        StreamArtistRecoveredTimingInventory.note(
            StreamArtistRecoveredTimingTypes.Input(
                parameter,
                actionId,
                key,
                oldHash,
                newHash,
                prior,
                value,
                floor,
                revision,
                revision + 1
            )
        );
        emit ArtistWindowChanged(1, parameter, prior, value, floor, revision + 1, actionId);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./StreamArtistExtensionFactory.sol";

/// @notice Constructor-only authentication of the compiler-linked factory and its original CREATE receipts.
library StreamArtistExtensionAdmission {
    bytes32 private constant DOMAIN = keccak256("6529STREAM_ARTIST_EXTENSION_BIRTH_V1");
    error InvalidExtensionBinding(address child);

    function identity(address factory, address[3] memory children, address[6] memory pins)
        internal
        view
    {
        _factory(factory);
        for (uint8 i; i < 3; ++i) {
            uint8 kind = i + 1;
            _require(
                factory,
                children[i],
                pins[0],
                kind,
                keccak256(abi.encode(DOMAIN, block.chainid, kind, pins))
            );
        }
    }

    function registry(
        address factory,
        address[3] memory children,
        address host,
        address coordinator
    ) internal view {
        _factory(factory);
        for (uint8 i; i < 3; ++i) {
            uint8 kind = i + 4;
            _require(
                factory,
                children[i],
                host,
                kind,
                keccak256(abi.encode(DOMAIN, block.chainid, kind, host, coordinator))
            );
        }
    }

    function _factory(address factory) private view {
        if (factory.codehash != keccak256(type(StreamArtistExtensionFactory).runtimeCode)) {
            revert InvalidExtensionBinding(factory);
        }
    }

    function _require(address factory, address child, address host, uint8 kind, bytes32 bindingHash)
        private
        view
    {
        StreamArtistExtensionFactory.Birth memory b =
            StreamArtistExtensionFactory(factory).birth(child);
        if (
            child.code.length == 0 || b.kind != kind || b.host != host || b.chainId != block.chainid
                || b.bindingHash != bindingHash || b.runtimeCodeHash != child.codehash
        ) revert InvalidExtensionBinding(child);
    }
}

