                _identityRecovery,
                _recoveryAdjudication,
                _identity,
                _rotations,
                _resolutions,
                _estate,
                _dormancy,
                o,
                call_
            );
        }
        return read(
            _identity,
            _delegations,
            _identityRevisions,
            _rotations,
            _identityContests,
            _succession,
            _resolutions,
            _estate,
            _unavailability,
            _identityRecovery,
            _dormancy,
            _stewardGrants,
            _stewardCapabilityGrants,
            _replay,
            o,
            call_
        );
