        private
        view
        returns (StreamArtistSanctionCandidate.Pins memory)
    {
        return FinalityReads.sanctionPins(
            _suite,
            deploymentChainId,
            collectionId,
            finalityRegistry,
            finalityRegistryCodeHash,
            finalityEvidenceProvider,
            finalityEvidenceProviderCodeHash
