            artists[k] = _artist(scope, scope.collections[k].artistId);
            for (uint256 j; j < rows[k].length; ++j) {
                T.RatificationRecord calldata r = rows[k][j];
                if (
                    r.recordHash == 0 || r.contentStateHash == 0 || r.metadataContract == address(0)
                ) {
