pragma solidity ^0.8.19;

import {
    StreamArtistRecoveredHydrationTypes as RH
} from "../../interfaces/stream/artist/StreamArtistRecoveredHydrationTypes.sol";
import {
    StreamArtistAuthorityHydrationTypes as AH
} from "../../interfaces/stream/artist/IStreamArtistAuthorityHydration.sol";
import {
    StreamArtistDelegationHydrationTypes as DH
} from "../../interfaces/stream/artist/IStreamArtistDelegationAuthorityHydration.sol";
import {
    StreamArtistEconomicsHydrationTypes as EH
} from "../../interfaces/stream/artist/IStreamArtistEconomicsAuthorityHydration.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";
import {
    StreamArtistSaleTypes as Sale
} from "../../interfaces/stream/artist/StreamArtistSaleTypes.sol";
import {
    IStreamArtistConsentOwner as Consent
} from "../../interfaces/stream/artist/IStreamArtistConsentOwner.sol";
import {
    IStreamArtistDelegatedConsentOwner as Delegated
} from "../../interfaces/stream/artist/IStreamArtistDelegatedConsentOwner.sol";
import {
    IStreamArtistEconomicsEvidence as Evidence
} from "../../interfaces/stream/artist/IStreamArtistEconomicsEvidence.sol";
import {
    IStreamArtistSaleConsentOwner as Sales
} from "../../interfaces/stream/artist/IStreamArtistSaleOwner.sol";
import {
    StreamArtistRecoveredHydrationProvenance as Provenance
} from "./StreamArtistRecoveredHydrationProvenance.sol";
import {
    StreamArtistRecoveredHydrationOwnerPayload as Payload
} from "./StreamArtistRecoveredHydrationOwnerPayload.sol";
import {
    StreamArtistEconomicsAssociation as Association
} from "./StreamArtistEconomicsAssociation.sol";
import { StreamArtistSaleHashes } from "./StreamArtistSaleHashes.sol";
import {
    StreamArtistRecoveredDelegatedConsentHydration as Base
} from "./StreamArtistRecoveredDelegatedConsentHydration.sol";
import {
    StreamArtistRecoveredBindingGenerations as G
} from "./StreamArtistRecoveredBindingGenerations.sol";

import { StreamArtistHashes } from "./StreamArtistHashes.sol";

import { StreamArtistRecoveredDisputeConsentHistory as History } from "./StreamArtistRecoveredDisputeConsentHistory.sol";

/// @notice Pure complete original consent-history validation; no storage or authority writes.
library StreamArtistRecoveredDisputeConsentValidation {
    bytes32 private constant POLICY = keccak256("consent_finality.replay.policy_consent_key");
    bytes32 private constant ECONOMICS = keccak256("consent_finality.replay.consent_key");
    bytes32 private constant SALE = keccak256("consent_finality.replay.sale_consent_key");
    uint256 private constant MAX_ROWS = 128;

    function validate(History.Bundle memory b, AH.Query memory q, RH.OwnerProvenance memory p) public pure {
        Provenance.validateOwner(p, 6);
        if (
            b.original.keys.length > MAX_ROWS || b.original.economics.length > MAX_ROWS
                || b.original.sales.length > MAX_ROWS
        ) revert T.UnsupportedProfile();
        if (
            b.original.provenance != RH.ownerProvenanceHash(p, 6) || q.artistId == 0
                || b.original.artistId != q.artistId || q.collectionId == 0
                || b.original.collectionId != q.collectionId || q.bindingHash == 0
                || b.original.bindingHash != q.bindingHash
                || b.original.policies.length != b.original.keys.length
                || keccak256(abi.encode(b.original.keys)) != keccak256(abi.encode(q.policies))
                || p.journal.length
                    != b.original.policies.length + b.original.economics.length
                        + b.original.sales.length
        ) _invalid();
        if (
            b.bindings.length == 0 || b.bindings.length > 128
                || b.bindings[b.bindings.length - 1].bindingHash != q.bindingHash
                || !b.bindings[b.bindings.length - 1].accepted
        ) _invalid();
        for (uint256 i; i < b.bindings.length; ++i) {
            T.Binding memory row = b.bindings[i];
            if (
                row.generation != i + 1 || row.artistId != q.artistId || row.bindingHash == 0
                    || (row.consentMode != 1 && row.consentMode != 2)
            ) _invalid();
        }
        _rows(b);
        (bytes32[] memory surfaces, bytes32[] memory scopes) = _journal(b, p);
        _eras(p);
        _aliases(p, surfaces, scopes);
    }

    function _rows(History.Bundle memory b) private pure {
        for (uint256 i; i < b.original.policies.length; ++i) {
            if (
                b.original.policies[i].recordHash == 0 || b.original.keys[i].phaseId == 0
                    || b.original.keys[i].policyHash == 0
            ) _invalid();
            for (uint256 j; j < i; ++j) {
                if (
                    b.original.policies[j].recordHash == b.original.policies[i].recordHash
                        || _policyScope(b.original.collectionId, b.original.keys[j])
                            == _policyScope(b.original.collectionId, b.original.keys[i])
                ) _invalid();
            }
        }
        for (uint256 i; i < b.original.economics.length; ++i) {
            EH.Row memory r = b.original.economics[i].item;
            T.EconomicsConsent memory t = r.terms;
            Evidence.Association memory a = r.association;
            if (
                r.recordHash == 0 || t.collectionId != b.original.collectionId
                    || t.resolver == address(0) || t.revenueClass == 0 || t.scope > 2
                    || (t.scope == 0 && (t.scopeId != 0 || t.assignmentHash == 0))
                    || (t.scope == 1 && t.scopeId != b.original.collectionId)
                    || (t.scope == 2 && t.scopeId == 0) || a.artistId != b.original.artistId
                    || !_binding(b, a.bindingGeneration, a.bindingHash, false)
                    || a.payloadHash != keccak256(abi.encode(t)) || a.originalRecord != r.recordHash
            ) _invalid();
            for (uint256 j; j < i; ++j) {
                if (
                    b.original.economics[j].item.recordHash == r.recordHash
                        || b.original.economics[j].item.association.payloadHash == a.payloadHash
                ) _invalid();
            }
        }
        for (uint256 i; i < b.original.sales.length; ++i) {
            DH.Sale memory row = b.original.sales[i];
            Sale.Record memory r = row.item;
            if (
                r.recordHash == 0 || r.artistId != b.original.artistId
                    || r.terms.collectionId != b.original.collectionId
                    || r.terms.saleAdapter == address(0) || r.terms.saleId == 0
                    || r.terms.saleConfigHash == 0 || r.signer == address(0) || r.signedAt == 0
                    || !_binding(b, r.bindingGeneration, r.bindingHash, row.grant != 0)
                    || (row.grant == 0
                            ? (r.authorityClass != 1 && r.authorityClass != 3)
                            : r.authorityClass != 2)
            ) _invalid();
            for (uint256 j; j < i; ++j) {
                if (
                    b.original.sales[j].item.recordHash == r.recordHash
                        || keccak256(abi.encode(b.original.sales[j].item.terms))
                            == keccak256(abi.encode(r.terms))
                ) _invalid();
            }
            bytes32 current = r.recordHash;
            for (uint256 j = i + 1; j < b.original.sales.length; ++j) {
                if (_lookup(b.original.sales[j].item.terms) == _lookup(r.terms)) {
                    current = b.original.sales[j].item.recordHash;
                }
            }
            if (row.current != current) _invalid();
        }
    }

    function _binding(History.Bundle memory b, uint64 generation, bytes32 hash, bool delegatedSale)
        private
        pure
        returns (bool)
    {
        if (generation == 0 || generation > b.bindings.length) return false;
        T.Binding memory row = b.bindings[generation - 1];
        return row.accepted && row.bindingHash == hash && (!delegatedSale || row.consentMode == 2);
    }

    function _journal(History.Bundle memory b, RH.OwnerProvenance memory p)
        private
        pure
        returns (bytes32[] memory surfaces, bytes32[] memory scopes)
    {
        surfaces = new bytes32[](p.journal.length);
        scopes = new bytes32[](p.journal.length);
        uint256 economics;
        uint256 sales;
        for (uint256 i; i < p.journal.length; ++i) {
            RH.JournalEntry memory row = p.journal[i];
            if (
                row.receipt.artistId != b.original.artistId
                    || row.receipt.collectionId != b.original.collectionId
            ) {
                _invalid();
            }
            for (uint256 j; j < i; ++j) {
                if (p.journal[j].receipt.recordHash == row.receipt.recordHash) _invalid();
            }
            if (row.receipt.operation == 14) {
                bool found;
                for (uint256 j; j < b.original.policies.length; ++j) {
                    if (b.original.policies[j].recordHash != row.receipt.recordHash) continue;
                    surfaces[i] = POLICY;
                    scopes[i] = _policyScope(b.original.collectionId, b.original.keys[j]);
                    found = true;
                }
                if (!found) _invalid();
            } else if (row.receipt.operation == 15) {
                if (economics >= b.original.economics.length) _invalid();
                EH.Row memory r = b.original.economics[economics++].item;
                if (r.recordHash != row.receipt.recordHash) _invalid();
                surfaces[i] = ECONOMICS;
                scopes[i] = r.association.payloadHash;
            } else if (row.receipt.operation == 16) {
                if (sales >= b.original.sales.length) _invalid();
                Sale.Record memory r = b.original.sales[sales++].item;
                if (
                    r.recordHash != row.receipt.recordHash
                        || StreamArtistSaleHashes.record(
                                _environment(p, row.position.point.environmentHash),
                                r.terms,
                                r.artistId,
                                r.signer,
                                r.authorityClass,
                                r.nonce,
                                r.signedAt
                            ) != r.recordHash
                ) _invalid();
                surfaces[i] = SALE;
                scopes[i] = keccak256(abi.encode(r.terms, r.bindingGeneration, r.bindingHash));
            } else {
                revert T.UnsupportedProfile();
            }
        }
        if (economics != b.original.economics.length || sales != b.original.sales.length) {
            _invalid();
        }
    }

    function _eras(RH.OwnerProvenance memory p) private pure {
        uint256 total;
        uint256 cursor;
        for (uint256 i; i < p.eras.length; ++i) {
            RH.OwnerEra memory era = p.eras[i];
            total += era.nativeCount;
            if (
                era.lowerRevision != (i == 0 ? 0 : 1)
                    || uint256(era.checkpoint.ownerState.revision)
                        != uint256(era.lowerRevision) + era.nativeCount
                    || era.checkpoint.nonceIndexCount != 0 || era.checkpoint.nonceRoot != 0
                    || era.checkpoint.replayCount != total
                    || (total == 0 && era.checkpoint.replayRoot != 0)
            ) _invalid();
            for (uint256 j; j < era.nativeCount; ++j) {
                // Both direct and delegated14/15/16 each commit and emit one native occurrence.
                if (
                    uint256(p.journal[cursor++].position.point.ownerRevision)
                        != uint256(era.lowerRevision) + j + 1
                ) _invalid();
            }
        }
    }

    function _aliases(
        RH.OwnerProvenance memory p,
        bytes32[] memory surfaces,
        bytes32[] memory scopes
    ) private pure {
        for (uint256 i; i < p.aliases.length; ++i) {
            RH.ReplayAlias memory a = p.aliases[i];
            if (a.cell.kind != 1 || a.cell.status != 2) _invalid();
            bool found;
            for (uint256 j; j < p.journal.length; ++j) {
                if (
                    a.surface != surfaces[j] || a.scope != scopes[j]
                        || a.cell.commitment != p.journal[j].receipt.recordHash
                ) continue;
                if (
                    keccak256(abi.encode(a.admittedAt))
                        != keccak256(abi.encode(p.journal[j].position.point))
                ) _invalid();
                found = true;
            }
            if (!found) _invalid();
        }
        // Unique original keys, immutable scopes, each era's complete replayCount and no alias
        // before its admission jointly retain every historical row and all later rekeyed cells.
    }

    function _environment(RH.OwnerProvenance memory p, bytes32 origin)
        private
        pure
        returns (StreamArtistHashes.Environment memory e)
    {
        for (uint256 i; i < p.origins.length; ++i) {
            if (p.eras[i].originHash == origin) {
                RH.OriginEnvironment memory o = p.origins[i];
                return StreamArtistHashes.Environment(o.chainId, o.registry, o.core, o.manager);
            }
        }
        _invalid();
    }

    function _policyScope(uint256 collectionId, AH.PolicyKey memory key)
        private
        pure
        returns (bytes32)
    {
        return keccak256(abi.encode(collectionId, key.phaseId, key.policyHash));
    }

    function _lookup(Sale.Consent memory p) private pure returns (bytes32) {
        return StreamArtistSaleHashes.lookup(p.collectionId, p.saleId, p.saleConfigHash);
    }

    function _invalid() private pure {
        revert RH.InvalidRecoveredHydrationProfile();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    StreamArtistRecoveredDisputeHistoryTypes as D
} from "./StreamArtistRecoveredDisputeHistoryTypes.sol";
import {
    StreamArtistRecoveredHydrationTypes as RH
} from "../../interfaces/stream/artist/StreamArtistRecoveredHydrationTypes.sol";
import {
    StreamArtistAttributionDisputeTypes as AD
} from "../../interfaces/stream/artist/IStreamArtistAttributionDisputes.sol";
import {
    StreamArtistDisputeWithdrawalTypes as W
} from "../../interfaces/stream/artist/IStreamArtistDisputeWithdrawal.sol";
import {
    StreamArtistRecoveredHydrationChronology as Clock
} from "./StreamArtistRecoveredHydrationChronology.sol";

/// @notice Immutable opening/counter/resolution/withdrawal chains and their actual latest heads.
/// @dev These predicates join the already authenticated complete source maps. Historical
/// records are never authorized again against the current principal or current grant head.
library StreamArtistRecoveredDisputeHistoryChains {
    function validate(D.Bundle memory b, RH.OwnerProvenance memory p) public pure {
        _validate(b, p, false, true);
    }

    /// @dev The new profile separately proves every original confirmed-state restoration.
    function validateSanctioned(D.Bundle memory b, RH.OwnerProvenance memory p) public pure {
        _validate(b, p, true, true);
    }

    /// @notice Original generation chains without interpreting the latest binding lifecycle.
    /// @dev The complete profile separately joins pending/terminal heads and sanctions.
    function validateGenerationChains(D.Bundle memory b, RH.OwnerProvenance memory p) public pure {
        _validate(b, p, true, false);
    }

    function _validate(
        D.Bundle memory b,
        RH.OwnerProvenance memory p,
        bool sanctioned,
        bool checkCurrent
    ) private pure {
        for (uint256 i; i < b.disputes.length; ++i) {
            D.DisputeRow memory r = b.disputes[i];
            AD.Record memory a = r.record;
            if (a.terms.disputeAction == 1) {
                bytes32 previous;
                for (uint256 j; j < i; ++j) {
                    AD.Record memory prior = b.disputes[j].record;
                    if (
                        prior.terms.disputeAction == 1
                            && prior.terms.bindingGeneration == a.terms.bindingGeneration
                    ) {
                        previous = prior.recordHash;
                        _closedBefore(b, j, r.point, p);
                    }
                }
                if (a.previousRecordHash != previous) _invalid();
                if (_reopened(b, r, p) && a.governanceActionId == 0) _invalid();
                _outcome(b, i, p, sanctioned);
            } else {
                uint256 opening = _opening(b, a.disputeRecordHash);
                D.DisputeRow memory o = b.disputes[opening];
                if (
                    opening >= i || o.record.terms.bindingGeneration != a.terms.bindingGeneration
                        || o.record.bindingHash != a.bindingHash
                        || !Clock.beforeOwner(p, 4, o.point, r.point)
                ) _invalid();
                bytes32 counter = _counterBefore(b, a.disputeRecordHash, r.point, p);
                if (
                    a.previousRecordHash
                        != (a.terms.disputeAction == 3
                                ? counter
                                : counter == 0 ? a.disputeRecordHash : counter)
                ) _invalid();
                _notClosedBefore(b, opening, r.point, p);
                if (
                    a.terms.disputeAction == 2
                        && (o.withdrawal.recordHash != a.recordHash
                            || o.withdrawal.counterStatementRecordHash != counter
                            || o.record.governanceActionId != 0
                            || o.record.signer != a.signer
                            || o.record.authorityClass != a.authorityClass
                            || keccak256(abi.encode(o.record.standing))
                                != keccak256(abi.encode(a.standing)))
                ) _invalid();
            }
        }
        for (uint256 i; i < b.resolutions.length; ++i) {
            D.ResolutionRow memory r = b.resolutions[i];
            uint256 opening = _opening(b, r.record.terms.disputeRecordHash);
            D.DisputeRow memory o = b.disputes[opening];
            if (
                o.record.terms.bindingGeneration != r.record.terms.bindingGeneration
                    || !Clock.beforeOwner(p, 4, o.point, r.point)
                    || r.record.resolvedAt < o.record.recordedAt || o.withdrawal.recordHash != 0
                    || r.record.terms.counterStatementRecordHash
                        != _counterBefore(b, o.record.recordHash, r.point, p)
                    || (_reopened(b, o, p) && r.record.actionClass != 2)
            ) _invalid();
            bytes32 previous;
            for (uint256 j; j < i; ++j) {
                if (
                    b.resolutions[j].record.terms.bindingGeneration
                        == r.record.terms.bindingGeneration
                ) {
                    previous = b.resolutions[j].record.actionId;
                }
            }
            if (r.record.previousResolutionActionId != previous) _invalid();
        }
        for (uint256 g; g < b.generations.length; ++g) {
            _head(b, uint64(g + 1), p, sanctioned, checkCurrent);
        }
    }

    function _head(
        D.Bundle memory b,
        uint64 generation,
        RH.OwnerProvenance memory p,
        bool sanctioned,
        bool checkCurrent
    ) private pure {
        AD.Head memory h = b.heads[generation - 1];
        uint256 latest = type(uint256).max;
        bytes32 resolution;
        for (uint256 i; i < b.disputes.length; ++i) {
            if (
                b.disputes[i].record.terms.bindingGeneration == generation
                    && b.disputes[i].record.terms.disputeAction == 1
            ) latest = i;
        }
        for (uint256 i; i < b.resolutions.length; ++i) {
            if (b.resolutions[i].record.terms.bindingGeneration == generation) {
                resolution = b.resolutions[i].record.actionId;
            }
        }
        if (latest == type(uint256).max) {
            AD.Head memory expected;
            expected.revocationReason = h.revocationReason;
            if (
                (h.revocationReason != 0 && h.revocationReason != 3)
                    || keccak256(abi.encode(h)) != keccak256(abi.encode(expected))
            ) _invalid();
        } else {
            D.DisputeRow memory o = b.disputes[latest];
            bytes32 counter;
            bool resolved;
            bool open = o.withdrawal.recordHash == 0;
            for (uint256 i; i < b.disputes.length; ++i) {
                if (
                    b.disputes[i].record.terms.disputeAction == 3
                        && b.disputes[i].record.disputeRecordHash == o.record.recordHash
                ) counter = b.disputes[i].record.recordHash;
            }
            for (uint256 i; i < b.resolutions.length; ++i) {
                if (b.resolutions[i].record.terms.disputeRecordHash == o.record.recordHash) {
                    resolved = true;
                    open = false;
                    if (
                        h.revocationReason != 3
                            && h.revocationReason
                                != (b.resolutions[i].record.terms.resolution == 2 ? 4 : 0)
                    ) _invalid();
                    if (
                        b.resolutions[i].record.terms.resolution == 1
                            && h.restoreState != b.resolutions[i].record.restoredState
                    ) _invalid();
                }
            }
            if (
                h.disputeRecordHash != o.record.recordHash
                    || h.counterStatementRecordHash != counter || h.resolutionActionId != resolution
                    || h.open != open || h.reopened != _reopened(b, o, p) || h.restoreState < 1
                    || h.restoreState > (sanctioned ? 3 : 2)
                    || (o.withdrawal.recordHash != 0
                        && (h.restoreState != o.withdrawal.restoredState
                            || (h.revocationReason != 0 && h.revocationReason != 3)))
                    || (open && h.revocationReason != (h.reopened ? 4 : 0))
                    || (!open && !resolved && o.withdrawal.recordHash == 0)
            ) _invalid();
        }
        if (h.revocationReason == 3) {
            bool executed;
            for (uint256 i; i < b.repudiations.length; ++i) {
                if (
                    b.repudiations[i].record.terms.bindingGeneration == generation
                        && b.repudiations[i].terminal.phase == 4
                ) executed = true;
            }
            if (!executed || h.open) _invalid();
        }
        if (checkCurrent && generation == b.current.generation) {
            if (
                (b.current.state == 4) != h.open
                    || (b.current.state == 5 && h.revocationReason != 3 && h.revocationReason != 4)
                    || ((b.current.state == 2 || (sanctioned && b.current.state == 3))
                        && h.revocationReason != 0)
            ) _invalid();
        }
    }

    function _outcome(
        D.Bundle memory b,
        uint256 index,
        RH.OwnerProvenance memory p,
        bool sanctioned
    ) private pure {
        D.DisputeRow memory opening = b.disputes[index];
        W.Outcome memory outcome = opening.withdrawal;
        if (outcome.recordHash == 0) {
            W.Outcome memory empty;
            if (keccak256(abi.encode(outcome)) != keccak256(abi.encode(empty))) _invalid();
            return;
        }
        if (
            (outcome.restoredState != 2 && (!sanctioned || outcome.restoredState != 3))
                || _reopened(b, opening, p)
        ) _invalid();
        uint256 matches;
        for (uint256 i = index + 1; i < b.disputes.length; ++i) {
            if (
                b.disputes[i].record.recordHash == outcome.recordHash
                    && b.disputes[i].record.terms.disputeAction == 2
                    && b.disputes[i].record.disputeRecordHash == opening.record.recordHash
            ) ++matches;
        }
        if (matches != 1) _invalid();
    }

    function _opening(D.Bundle memory b, bytes32 key) private pure returns (uint256) {
        for (uint256 i; i < b.disputes.length; ++i) {
            if (
                b.disputes[i].record.recordHash == key
                    && b.disputes[i].record.terms.disputeAction == 1
            ) return i;
        }
        _invalid();
    }

    function _counterBefore(
        D.Bundle memory b,
        bytes32 opening,
        RH.Point memory point,
        RH.OwnerProvenance memory p
    ) private pure returns (bytes32 key) {
        for (uint256 i; i < b.disputes.length; ++i) {
            D.DisputeRow memory r = b.disputes[i];
            if (
                r.record.terms.disputeAction == 3 && r.record.disputeRecordHash == opening
                    && Clock.beforeOwner(p, 4, r.point, point)
            ) key = r.record.recordHash;
        }
    }

    function _reopened(D.Bundle memory b, D.DisputeRow memory opening, RH.OwnerProvenance memory p)
        private
        pure
        returns (bool)
    {
        uint8 last;
        for (uint256 i; i < b.resolutions.length; ++i) {
            D.ResolutionRow memory r = b.resolutions[i];
            if (
                r.record.terms.bindingGeneration == opening.record.terms.bindingGeneration
                    && Clock.beforeOwner(p, 4, r.point, opening.point)
            ) last = r.record.terms.resolution;
        }
        return last == 2;
    }

    function _closedBefore(
        D.Bundle memory b,
        uint256 opening,
        RH.Point memory point,
        RH.OwnerProvenance memory p
    ) private pure {
        bool closed;
        for (uint256 i; i < b.resolutions.length; ++i) {
            if (
                b.resolutions[i].record.terms.disputeRecordHash
                        == b.disputes[opening].record.recordHash
                    && Clock.beforeOwner(p, 4, b.resolutions[i].point, point)
            ) closed = true;
        }
        bytes32 withdrawal = b.disputes[opening].withdrawal.recordHash;
        for (uint256 i; i < b.disputes.length; ++i) {
            if (
                withdrawal != 0 && b.disputes[i].record.recordHash == withdrawal
                    && Clock.beforeOwner(p, 4, b.disputes[i].point, point)
            ) closed = true;
        }
        if (!closed) _invalid();
    }

    function _notClosedBefore(
        D.Bundle memory b,
        uint256 opening,
        RH.Point memory point,
        RH.OwnerProvenance memory p
    ) private pure {
        for (uint256 i; i < b.resolutions.length; ++i) {
            if (
                b.resolutions[i].record.terms.disputeRecordHash
                        == b.disputes[opening].record.recordHash
                    && Clock.beforeOwner(p, 4, b.resolutions[i].point, point)
            ) _invalid();
        }
        bytes32 withdrawal = b.disputes[opening].withdrawal.recordHash;
        for (uint256 i; i < b.disputes.length; ++i) {
            if (
                withdrawal != 0 && b.disputes[i].record.recordHash == withdrawal
                    && Clock.beforeOwner(p, 4, b.disputes[i].point, point)
            ) _invalid();
        }
    }

    function _invalid() private pure {
        revert RH.InvalidRecoveredHydrationProfile();
    }
}

