    ) public pure returns (bytes32 id, bytes memory encoded) {
        id = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ONBOARDING_OPERATION_EVIDENCE_V1"),
                chainId,
                registry,
                coordinator,
                uint16(60),
                actor,
                value
            )
        );
        encoded = abi.encode(
            uint16(1), configurationHash, uint16(60), actor, value, before_, after_, carrier
        );
    }
}

