pragma solidity ^0.8.19;

import {
    StreamArtistRecoveredHydrationTypes as RH
} from "../../interfaces/stream/artist/StreamArtistRecoveredHydrationTypes.sol";
import {
    IStreamArtistRecoveredHydrationOwner as Source,
    IStreamArtistRecoveredNativeChronology as NativeChronology
} from "../../interfaces/stream/artist/IStreamArtistRecoveredHydration.sol";
import {
    IStreamArtistAuthorityHydrationCoordinator as Coordinator,
    IStreamArtistAuthorityHydrationOwner as PreviousOwner
} from "../../interfaces/stream/artist/IStreamArtistAuthorityHydration.sol";
import {
    IStreamArtistAuthorityCheckpoint as CP
} from "../../interfaces/stream/artist/IStreamArtistAuthorityCheckpoint.sol";
import { IStreamArtistOwner } from "../../interfaces/stream/artist/IStreamArtistOwner.sol";
import {
    IStreamArtistNativeReceipts as Native
} from "../../interfaces/stream/artist/IStreamArtistHistory.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";
import {
    StreamArtistRecoveredHydrationChronology as Chronology
} from "./StreamArtistRecoveredHydrationChronology.sol";
import {
    StreamArtistRecoveredHydrationCodec as Codec
} from "./StreamArtistRecoveredHydrationCodec.sol";

/// @notice Flattened original environments, complete native occurrences, and cumulative guard keys.
/// @dev Pure validation authenticates shape, not authority. validateSource additionally binds the
/// exact imported prefixes and actual native/current-guard suffixes to all seven fixed owners. The caller
/// still authenticates the governed predecessor, cutover57, verified lanes, semantic owner facts,
/// nonce inventories, and the destination suite. No recursive historical call chain is followed.
library StreamArtistRecoveredHydrationProvenance {
    function environment(RH.Provenance memory p, bytes32 hash)
        public
        pure
        returns (RH.OriginEnvironment memory result)
    {
        bool found;
        for (uint256 i; i < p.origins.length; ++i) {
            if (RH.originHash(p.origins[i]) != hash) continue;
            if (found) revert RH.InvalidRecoveredHydrationProvenance();
            found = true;
            result = p.origins[i];
        }
        if (!found) revert RH.InvalidRecoveredHydrationProvenance();
    }

    function validate(RH.Provenance memory p) public pure returns (bytes32 commitment) {
        if (
            p.origins.length == 0 || p.origins.length != p.eras.length
                || p.eras.length > RH.MAX_ERAS
        ) {
            revert RH.InvalidRecoveredHydrationProvenance();
        }
        for (uint256 i; i < p.eras.length; ++i) {
            _origin(p, i);
        }
        uint256 journalCount;
        uint256 aliasCount;
        for (uint8 i; i < 7; ++i) {
            journalCount += p.journals[i].length;
            aliasCount += p.aliases[i].length;
            if (journalCount > RH.MAX_JOURNAL_ENTRIES || aliasCount > RH.MAX_REPLAY_ALIASES) {
                revert RH.InvalidRecoveredHydrationProvenance();
            }
            _journal(p, i);
            _aliases(p, i);
        }
        return RH.provenanceHash(p);
    }

    /// @notice Exact original nonce-index and full leaf/ancestor-word export, including exhaustion.
    /// @dev Current cells cannot reconstruct a rolling nonceRoot. The fixed producer checkpoint
    /// and every indexed getter must match; the Coordinator repeats its source header check.
    function validateNonces(
        address owner,
        CP.Checkpoint memory expected,
        RH.NonceInventory[] memory n
    ) public view returns (bytes32) {
        if (
            expected.schema != RH.CHECKPOINT || n.length > RH.MAX_NONCE_INDICES
                || n.length != expected.nonceIndexCount
                || keccak256(abi.encode(CP(owner).authorityCheckpoint()))
                    != keccak256(abi.encode(expected))
        ) revert RH.InvalidRecoveredHydrationProvenance();
        for (uint256 i; i < n.length; ++i) {
            CP.NonceIndex memory index = n[i].index;
            if (
                index.kind == 0 || index.kind > 5 || index.key == 0 || index.prefixCount == 0
                    || index.prefixCount > RH.MAX_NONCE_PREFIXES
                    || index.prefixCount != n[i].words.length
                    || keccak256(abi.encode(CP(owner).authorityNonceIndexAt(i)))
                        != keccak256(abi.encode(index))
            ) revert RH.InvalidRecoveredHydrationProvenance();
            for (uint256 prior; prior < i; ++prior) {
                if (n[prior].index.kind == index.kind && n[prior].index.key == index.key) {
                    revert RH.InvalidRecoveredHydrationProvenance();
                }
            }
            for (uint256 j; j < n[i].words.length; ++j) {
                (uint256 prefix, uint256[32] memory words, bool exhausted) =
                    CP(owner).authorityNonceWordAt(index.kind, index.key, j);
                if (
                    prefix != n[i].words[j].prefix || exhausted != n[i].words[j].exhausted
                        || keccak256(abi.encode(words))
                            != keccak256(abi.encode(n[i].words[j].words))
                ) revert RH.InvalidRecoveredHydrationProvenance();
                for (uint256 prior; prior < j; ++prior) {
                    if (n[i].words[prior].prefix == prefix) {
                        revert RH.InvalidRecoveredHydrationProvenance();
                    }
                }
            }
        }
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_RECOVERED_HYDRATION_NONCES_V1"),
                RH.VERSION,
                owner,
                expected,
                n
            )
        );
    }

    function validateSource(RH.Provenance memory p, address sourceCoordinator)
        public
        view
        returns (bytes32 commitment)
    {
        commitment = validate(p);
        uint256 last = p.eras.length - 1;
        RH.OriginEnvironment memory current = p.origins[last];
        if (current.coordinator != sourceCoordinator) {
            revert RH.InvalidRecoveredHydrationProvenance();
        }
        for (uint256 i; i < p.origins.length; ++i) {
            _fixedEnvironment(p.origins[i]);
        }
        for (uint8 i; i < 7; ++i) {
            _sourceOwner(p, last, i);
        }
    }

    /// @notice Owner-local validation for a fixed typed exporter receiving verified-key witnesses.
    /// @dev Reads only this owner's mutable state and the constructor-fixed suite configuration.
    /// It cannot validate another owner's semantic state or replace the Coordinator's complete join.
    function validateOwnerSource(RH.OwnerProvenance memory local, uint8 ownerIndex, address owner)
        public
        view
        returns (bytes32)
    {
        RH.Provenance memory p = _validatedOwner(local, ownerIndex);
        uint256 last = p.eras.length - 1;
        RH.OriginEnvironment memory o = p.origins[last];
        if (o.owners[ownerIndex] != owner || o.chainId != block.chainid) {
            revert RH.InvalidRecoveredHydrationProvenance();
        }
        _fixedOwner(o, ownerIndex);
        _fixedSuite(o);
        _sourceOwner(p, last, ownerIndex);
        return RH.ownerProvenanceHash(local, ownerIndex);
    }

    /// @notice Pure owner-local shape validation for an already admitted destination import.
    /// @dev No external source reads and no authority inference. The Coordinator authenticates
    /// the complete seven-owner certificate before the original guarded operation60 apply.
    function validateOwner(RH.OwnerProvenance memory local, uint8 ownerIndex)
        public
        pure
        returns (bytes32)
    {
        _validatedOwner(local, ownerIndex);
        return RH.ownerProvenanceHash(local, ownerIndex);
    }

    function _validatedOwner(RH.OwnerProvenance memory local, uint8 ownerIndex)
        private
        pure
        returns (RH.Provenance memory p)
    {
        if (
            ownerIndex >= 7 || local.origins.length == 0
                || local.origins.length != local.eras.length || local.eras.length > RH.MAX_ERAS
                || local.journal.length > RH.MAX_JOURNAL_ENTRIES
                || local.aliases.length > RH.MAX_REPLAY_ALIASES
        ) revert RH.InvalidRecoveredHydrationProvenance();
        p.origins = local.origins;
        p.eras = new RH.Era[](local.eras.length);
        p.journals[ownerIndex] = local.journal;
        p.aliases[ownerIndex] = local.aliases;
        for (uint256 i; i < local.eras.length; ++i) {
            p.eras[i].originHash = local.eras[i].originHash;
            p.eras[i].checkpoints[ownerIndex] = local.eras[i].checkpoint;
            p.eras[i].nativeCounts[ownerIndex] = local.eras[i].nativeCount;
            p.eras[i].lowerRevisions[ownerIndex] = local.eras[i].lowerRevision;
            p.eras[i].priorImportCommitment = local.eras[i].priorImportCommitment;
        }
        for (uint256 i; i < p.eras.length; ++i) {
            _originBase(p, i);
            _ownerEra(p, i, ownerIndex);
        }
        _journal(p, ownerIndex);
        _aliases(p, ownerIndex);
    }

    /// @notice Matches an already structurally validated complete export to one saved owner prefix.
    /// @dev The actual fixed-owner getter supplies prefix/commitment/revision. Empty is permitted
    /// only for the genuine first era, with both the marker and local import revision absent.
    function validateImportedPrefix(
        RH.Provenance memory p,
        uint8 ownerIndex,
        RH.OwnerProvenance memory prefix,
        bytes32 importCommitment,
        uint64 importedAtRevision
    ) public pure {
        if (ownerIndex >= 7 || p.eras.length == 0 || p.origins.length != p.eras.length) {
            revert RH.InvalidRecoveredHydrationProvenance();
        }
        uint256 last = p.eras.length - 1;
        if (
            importCommitment != p.eras[last].priorImportCommitment
                || importedAtRevision != p.eras[last].lowerRevisions[ownerIndex]
                || (last == 0 && (importCommitment != 0 || importedAtRevision != 0))
                || (last != 0 && (importCommitment == 0 || importedAtRevision == 0))
        ) revert RH.InvalidRecoveredHydrationProvenance();
        RH.OwnerProvenance memory expected;
        expected.origins = new RH.OriginEnvironment[](last);
        expected.eras = new RH.OwnerEra[](last);
        uint256 oldRows;
        for (uint256 i; i < last; ++i) {
            expected.origins[i] = p.origins[i];
            RH.Era memory era = p.eras[i];
            expected.eras[i] = RH.OwnerEra(
                era.originHash,
                era.checkpoints[ownerIndex],
                era.nativeCounts[ownerIndex],
                era.lowerRevisions[ownerIndex],
                era.priorImportCommitment
            );
            oldRows += era.nativeCounts[ownerIndex];
        }
        if (oldRows > p.journals[ownerIndex].length) {
            revert RH.InvalidRecoveredHydrationProvenance();
        }
        expected.journal = new RH.JournalEntry[](oldRows);
        for (uint256 i; i < oldRows; ++i) {
            expected.journal[i] = p.journals[ownerIndex][i];
        }
        uint256 oldAliases;
        for (uint256 i; i < p.aliases[ownerIndex].length; ++i) {
            if (p.aliases[ownerIndex][i].originHash != p.eras[last].originHash) ++oldAliases;
        }
        expected.aliases = new RH.ReplayAlias[](oldAliases);
        uint256 cursor;
        for (uint256 i; i < p.aliases[ownerIndex].length; ++i) {
            RH.ReplayAlias memory alias_ = p.aliases[ownerIndex][i];
            if (alias_.originHash != p.eras[last].originHash) expected.aliases[cursor++] = alias_;
        }
        if (
            RH.ownerProvenanceHash(prefix, ownerIndex)
                != RH.ownerProvenanceHash(expected, ownerIndex)
        ) {
            revert RH.InvalidRecoveredHydrationProvenance();
        }
    }

    function _origin(RH.Provenance memory p, uint256 i) private pure {
        _originBase(p, i);
        for (uint8 ownerIndex; ownerIndex < 7; ++ownerIndex) {
            _ownerEra(p, i, ownerIndex);
        }
    }

    function _originBase(RH.Provenance memory p, uint256 i) private pure {
        RH.OriginEnvironment memory o = p.origins[i];
        RH.Era memory era = p.eras[i];
        if (
            o.chainId == 0 || o.chainId != p.origins[0].chainId || o.registry == address(0)
                || o.coordinator == address(0) || o.archive == address(0) || o.core == address(0)
                || o.manager == address(0) || o.suiteConfigurationHash == 0
                || o.core != p.origins[0].core || o.manager != p.origins[0].manager
                || RH.originHash(o) != era.originHash || (i == 0 && era.priorImportCommitment != 0)
                || (i != 0 && era.priorImportCommitment == 0)
        ) revert RH.InvalidRecoveredHydrationProvenance();
        for (uint256 prior; prior < i; ++prior) {
            if (
                p.eras[prior].originHash == era.originHash
                    || p.origins[prior].registry == o.registry
                    || p.origins[prior].coordinator == o.coordinator
            ) revert RH.InvalidRecoveredHydrationProvenance();
        }
        for (uint8 ownerIndex; ownerIndex < 7; ++ownerIndex) {
            for (uint8 other; other < ownerIndex; ++other) {
                if (o.owners[ownerIndex] == o.owners[other]) {
                    revert RH.InvalidRecoveredHydrationProvenance();
                }
            }
        }
    }

    function _ownerEra(RH.Provenance memory p, uint256 i, uint8 ownerIndex) private pure {
        RH.OriginEnvironment memory o = p.origins[i];
        RH.Era memory era = p.eras[i];
        CP.Checkpoint memory cp = era.checkpoints[ownerIndex];
        if (
            o.owners[ownerIndex] == address(0) || o.ownerCodeHashes[ownerIndex] == 0
                || cp.schema != RH.CHECKPOINT
                || cp.ownerState.domainId != RH.ownerDomain(ownerIndex)
                || cp.ownerState.stateRoot == 0 || cp.ownerState.recordChainTip == 0
                || era.lowerRevisions[ownerIndex] > cp.ownerState.revision
                || (i == 0 && era.lowerRevisions[ownerIndex] != 0)
                || (i != 0 && era.lowerRevisions[ownerIndex] == 0)
        ) revert RH.InvalidRecoveredHydrationProvenance();
    }

    function _journal(RH.Provenance memory p, uint8 ownerIndex) private pure {
        uint256 cursor;
        for (uint256 era; era < p.eras.length; ++era) {
            uint64 previousRevision = p.eras[era].lowerRevisions[ownerIndex];
            for (uint256 j; j < p.eras[era].nativeCounts[ownerIndex]; ++j) {
                if (cursor >= p.journals[ownerIndex].length) {
                    revert RH.InvalidRecoveredHydrationProvenance();
                }
                RH.JournalEntry memory entry = p.journals[ownerIndex][cursor++];
                RH.Point memory point = entry.position.point;
                if (
                    point.environmentHash != p.eras[era].originHash
                        || point.ownerIndex != ownerIndex || entry.position.nativeIndex != j
                        || point.ownerRevision <= p.eras[era].lowerRevisions[ownerIndex]
                        || point.ownerRevision < previousRevision || entry.receipt.recordHash == 0
                        || entry.receipt.operation == 0
                        || (entry.receipt.operation > 59 && entry.receipt.operation != 61)
                        || (entry.receipt.artistId == 0 && entry.receipt.collectionId == 0)
                ) revert RH.InvalidRecoveredHydrationProvenance();
                Chronology.validatePoint(p, point);
                previousRevision = point.ownerRevision;
            }
        }
        if (cursor != p.journals[ownerIndex].length) {
            revert RH.InvalidRecoveredHydrationProvenance();
        }
    }

    function _aliases(RH.Provenance memory p, uint8 ownerIndex) private pure {
        uint256[] memory counts = new uint256[](p.eras.length);
        bytes32 previousKey;
        for (uint256 i; i < p.aliases[ownerIndex].length; ++i) {
            RH.ReplayAlias memory a = p.aliases[ownerIndex][i];
            uint256 keyEra = _era(p, a.originHash);
            uint256 mutationEra = _era(p, a.admittedAt.environmentHash);
            RH.OriginEnvironment memory o = p.origins[keyEra];
            if (
                a.ownerIndex != ownerIndex || a.originalKey <= previousKey || a.cell.status == 0
                    || a.admittedAt.ownerIndex != ownerIndex || mutationEra > keyEra
                    || a.admittedAt.ownerRevision != a.cell.touchedRevision
                    || a.originalKey
                        != keccak256(
                            abi.encode(
                                keccak256("6529STREAM_ARTIST_OWNER_REPLAY_KEY_V2"),
                                o.chainId,
                                o.registry,
                                o.coordinator,
                                o.archive,
                                o.owners[ownerIndex],
                                RH.ownerDomain(ownerIndex),
                                a.surface,
                                a.scope
                            )
                        )
            ) revert RH.InvalidRecoveredHydrationProvenance();
            Chronology.validatePoint(p, a.admittedAt);
            previousKey = a.originalKey;
            ++counts[keyEra];
        }
        for (uint256 i; i < counts.length; ++i) {
            if (counts[i] != p.eras[i].checkpoints[ownerIndex].replayCount) {
                revert RH.InvalidRecoveredHydrationProvenance();
            }
        }
    }

    function _era(RH.Provenance memory p, bytes32 hash) private pure returns (uint256) {
        for (uint256 i; i < p.eras.length; ++i) {
            if (p.eras[i].originHash == hash) return i;
        }
        revert RH.InvalidRecoveredHydrationProvenance();
    }

    function _fixedEnvironment(RH.OriginEnvironment memory o) private view {
        if (o.chainId != block.chainid) revert RH.InvalidRecoveredHydrationProvenance();
        _fixedSuite(o);
        for (uint8 i; i < 7; ++i) {
            _fixedOwner(o, i);
        }
    }

    function _fixedSuite(RH.OriginEnvironment memory o) private view {
        T.SuiteConfiguration memory suite = Coordinator(o.coordinator).authorityHydrationSuite();
        if (
            keccak256(abi.encode(suite)) != o.suiteConfigurationHash || suite.registry != o.registry
                || suite.archive != o.archive || suite.core != o.core
                || suite.mintManager != o.manager
                || keccak256(abi.encode(suite.owners)) != keccak256(abi.encode(o.owners))
        ) revert RH.InvalidRecoveredHydrationProvenance();
        // Runtime pins are immutable environment facts, not cross-owner semantic reads.
        for (uint8 i; i < 7; ++i) {
            if (o.owners[i].code.length == 0 || o.owners[i].codehash != o.ownerCodeHashes[i]) {
                revert RH.InvalidRecoveredHydrationProvenance();
            }
        }
    }

    function _fixedOwner(RH.OriginEnvironment memory o, uint8 i) private view {
        IStreamArtistOwner owner = IStreamArtistOwner(o.owners[i]);
        if (
            o.owners[i].code.length == 0 || o.owners[i].codehash != o.ownerCodeHashes[i]
                || owner.artistRegistry() != o.registry
                || owner.operationCoordinator() != o.coordinator || owner.archiveV2() != o.archive
                || owner.core() != o.core || owner.mintManager() != o.manager
                || owner.deploymentChainId() != o.chainId || owner.domainId() != RH.ownerDomain(i)
        ) revert RH.InvalidRecoveredHydrationProvenance();
    }

    function _sourceOwner(RH.Provenance memory p, uint256 last, uint8 i) private view {
        address owner = p.origins[last].owners[i];
        Source source = Source(owner);
        Codec.requireCapability(
            source.recoveredAuthorityHydrationCapability(), i, last == 0 ? 0 : RH.REPEATED_IMPORT
        );
        (RH.OwnerProvenance memory prefix, bytes32 importCommitment, uint64 importedAtRevision) =
            source.recoveredHydrationImportedPrefix();
        if (PreviousOwner(owner).authorityHydrationCommitment() != importCommitment) {
            revert RH.InvalidRecoveredHydrationProvenance();
        }
        validateImportedPrefix(p, i, prefix, importCommitment, importedAtRevision);
        if (
            Native(owner).artistNativeReceiptCount() != p.eras[last].nativeCounts[i]
                || keccak256(abi.encode(CP(owner).authorityCheckpoint()))
                    != keccak256(abi.encode(p.eras[last].checkpoints[i]))
        ) revert RH.InvalidRecoveredHydrationProvenance();
        for (uint256 j; j < p.journals[i].length; ++j) {
            RH.JournalEntry memory entry = p.journals[i][j];
            if (entry.position.point.environmentHash != p.eras[last].originHash) continue;
            if (
                keccak256(
                            abi.encode(
                                Native(owner).artistNativeReceiptAt(entry.position.nativeIndex)
                            )
                        ) != keccak256(abi.encode(entry.receipt))
                    || NativeChronology(owner)
                            .artistNativeReceiptRevisionAt(entry.position.nativeIndex)
                        != entry.position.point.ownerRevision
            ) revert RH.InvalidRecoveredHydrationProvenance();
        }
        _liveKeys(p, last, i, owner);
    }

    function _liveKeys(RH.Provenance memory p, uint256 last, uint8 i, address owner) private view {
        for (uint256 j; j < p.eras[last].checkpoints[i].replayCount; ++j) {
            (bytes32 key, T.ReplayCell memory cell) = CP(owner).authorityReplayAt(j);
            bool found;
            for (uint256 k; k < p.aliases[i].length; ++k) {
                RH.ReplayAlias memory a = p.aliases[i][k];
                if (a.originalKey != key) continue;
                if (
                    a.originHash != p.eras[last].originHash
                        || keccak256(abi.encode(a.cell)) != keccak256(abi.encode(cell))
                        || keccak256(abi.encode(IStreamArtistOwner(owner).replayCell(key)))
                            != keccak256(abi.encode(cell))
                        || keccak256(abi.encode(Source(owner).recoveredHydrationReplayPoint(key)))
                            != keccak256(abi.encode(a.admittedAt))
                ) revert RH.InvalidRecoveredHydrationProvenance();
                found = true;
                break;
            }
            if (!found) revert RH.InvalidRecoveredHydrationProvenance();
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import {
    StreamArtistRecoveredHydrationTypes as RH
} from "../../interfaces/stream/artist/StreamArtistRecoveredHydrationTypes.sol";
import {
    IStreamArtistRecoveredHydrationOwner as Owner,
    IStreamArtistRecoveredNativeChronology as NativeChronology
} from "../../interfaces/stream/artist/IStreamArtistRecoveredHydration.sol";
import {
    StreamArtistAuthorityHydrationTypes as AH,
    IStreamArtistAuthorityHydrationOwner as HydratedOwner
} from "../../interfaces/stream/artist/IStreamArtistAuthorityHydration.sol";
import {
    IStreamArtistAuthorityCheckpoint as CP
} from "../../interfaces/stream/artist/IStreamArtistAuthorityCheckpoint.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";
import {
    IStreamArtistNativeReceipts as Native
} from "../../interfaces/stream/artist/IStreamArtistHistory.sol";
import {
    StreamArtistRecoveredHydrationProvenance as Provenance
} from "./StreamArtistRecoveredHydrationProvenance.sol";
import {
    StreamArtistRecoveredHydrationGuards as Guards
} from "./StreamArtistRecoveredHydrationGuards.sol";

/// @notice Assembles complete flattened provenance using exact original source getter results.
/// @dev Caller still proves governed predecessor/cutover/lane admission and every semantic codec.
/// Replay preimages are necessary witnesses, never replacements for actual checkpoint key/cells.
library StreamArtistRecoveredHydrationSource {
    function collect(
        T.SuiteConfiguration memory source,
        address sourceCoordinator,
        AH.Origin[][7] memory origins
    ) public view returns (RH.Provenance memory p) {
        RH.OwnerProvenance[7] memory prefixes;
        uint64[7] memory importedAt;
        bytes32 importCommitment;
        for (uint8 i; i < 7; ++i) {
            bytes32 commitment;
            (prefixes[i], commitment, importedAt[i]) =
                Owner(source.owners[i]).recoveredHydrationImportedPrefix();
            if (
                commitment != HydratedOwner(source.owners[i]).authorityHydrationCommitment()
                    || (i != 0 && commitment != importCommitment)
                    || (commitment == 0
                            ? importedAt[i] != 0 || prefixes[i].origins.length != 0
                            || prefixes[i].eras.length != 0 || prefixes[i].journal.length != 0
                            || prefixes[i].aliases.length != 0
                            : importedAt[i] == 0 || prefixes[i].origins.length == 0)
            ) revert RH.InvalidRecoveredHydrationProvenance();
            if (i == 0) importCommitment = commitment;
            if (
                prefixes[i].origins.length != prefixes[0].origins.length
                    || prefixes[i].eras.length != prefixes[0].origins.length
                    || keccak256(abi.encode(prefixes[i].origins))
                        != keccak256(abi.encode(prefixes[0].origins))
            ) revert RH.InvalidRecoveredHydrationProvenance();
        }
        uint256 currentEra = prefixes[0].origins.length;
        if (currentEra >= RH.MAX_ERAS) revert RH.InvalidRecoveredHydrationProvenance();
        p.origins = new RH.OriginEnvironment[](currentEra + 1);
        p.eras = new RH.Era[](currentEra + 1);
        for (uint256 j; j < currentEra; ++j) {
            p.origins[j] = prefixes[0].origins[j];
            p.eras[j].originHash = RH.originHash(p.origins[j]);
            p.eras[j].priorImportCommitment = prefixes[0].eras[j].priorImportCommitment;
            for (uint8 i; i < 7; ++i) {
                RH.OwnerEra memory era = prefixes[i].eras[j];
                if (
                    era.originHash != p.eras[j].originHash
                        || era.priorImportCommitment != p.eras[j].priorImportCommitment
                ) revert RH.InvalidRecoveredHydrationProvenance();
                p.eras[j].checkpoints[i] = era.checkpoint;
                p.eras[j].nativeCounts[i] = era.nativeCount;
                p.eras[j].lowerRevisions[i] = era.lowerRevision;
            }
        }
        p.origins[currentEra] = _environment(source, sourceCoordinator);
        bytes32 currentOrigin = RH.originHash(p.origins[currentEra]);
        p.eras[currentEra].originHash = currentOrigin;
        p.eras[currentEra].priorImportCommitment = importCommitment;
        for (uint8 i; i < 7; ++i) {
            address owner = source.owners[i];
            CP.Checkpoint memory cp = CP(owner).authorityCheckpoint();
            uint256 count = Native(owner).artistNativeReceiptCount();
            if (
                prefixes[i].journal.length > RH.MAX_JOURNAL_ENTRIES
                    || count > RH.MAX_JOURNAL_ENTRIES - prefixes[i].journal.length
                    || prefixes[i].aliases.length > RH.MAX_REPLAY_ALIASES
                    || cp.replayCount > RH.MAX_REPLAY_ALIASES - prefixes[i].aliases.length
                    || origins[i].length != cp.replayCount
            ) revert RH.InvalidRecoveredHydrationProvenance();
            p.eras[currentEra].checkpoints[i] = cp;
            p.eras[currentEra].nativeCounts[i] = count;
            p.eras[currentEra].lowerRevisions[i] = importedAt[i];
            p.journals[i] = _journal(owner, i, currentOrigin, count, prefixes[i].journal);
            p.aliases[i] = _aliases(p.origins[currentEra], i, origins[i], prefixes[i].aliases);
        }
        Provenance.validateSource(p, sourceCoordinator);
    }

    function _environment(T.SuiteConfiguration memory s, address coordinator)
        private
        view
        returns (RH.OriginEnvironment memory o)
    {
        o.chainId = block.chainid;
        o.registry = s.registry;
        o.coordinator = coordinator;
        o.archive = s.archive;
        o.owners = s.owners;
        for (uint8 i; i < 7; ++i) {
            o.ownerCodeHashes[i] = s.owners[i].codehash;
        }
        o.core = s.core;
        o.manager = s.mintManager;
        o.suiteConfigurationHash = keccak256(abi.encode(s));
    }

    function _journal(
        address owner,
        uint8 ownerIndex,
        bytes32 currentOrigin,
        uint256 count,
        RH.JournalEntry[] memory prefix
    ) private view returns (RH.JournalEntry[] memory rows) {
        rows = new RH.JournalEntry[](prefix.length + count);
        for (uint256 i; i < prefix.length; ++i) {
            rows[i] = prefix[i];
        }
        for (uint256 i; i < count; ++i) {
            rows[prefix.length + i] = RH.JournalEntry(
                RH.Position(
                    RH.Point(
                        currentOrigin,
                        ownerIndex,
                        NativeChronology(owner).artistNativeReceiptRevisionAt(i)
                    ),
                    i
                ),
                Native(owner).artistNativeReceiptAt(i)
            );
        }
    }

    function _aliases(
        RH.OriginEnvironment memory source,
        uint8 ownerIndex,
        AH.Origin[] memory origins,
        RH.ReplayAlias[] memory prefix
    ) private view returns (RH.ReplayAlias[] memory aliases) {
        aliases = new RH.ReplayAlias[](prefix.length + origins.length);
        for (uint256 i; i < prefix.length; ++i) {
            aliases[i] = prefix[i];
        }
        address owner = source.owners[ownerIndex];
        bytes32 originHash = RH.originHash(source);
        for (uint256 i; i < origins.length; ++i) {
            (bytes32 key, T.ReplayCell memory cell) = CP(owner).authorityReplayAt(i);
            if (key != Guards.replayKey(source, ownerIndex, origins[i]) || cell.status == 0) {
                revert RH.InvalidRecoveredHydrationProvenance();
            }
            aliases[prefix.length + i] = RH.ReplayAlias(
                originHash,
                ownerIndex,
                origins[i].surface,
                origins[i].scope,
                key,
                cell,
                Owner(owner).recoveredHydrationReplayPoint(key)
            );
        }
        return _sort(aliases);
    }

    /// @dev Bounded stable merge sort avoids quadratic work over the complete cumulative keys.
    function _sort(RH.ReplayAlias[] memory aliases) private pure returns (RH.ReplayAlias[] memory) {
        if (aliases.length < 2) return aliases;
        RH.ReplayAlias[] memory scratch = new RH.ReplayAlias[](aliases.length);
        for (uint256 width = 1; width < aliases.length; width *= 2) {
            for (uint256 first; first < aliases.length; first += width * 2) {
                uint256 middle = first + width;
                if (middle > aliases.length) middle = aliases.length;
                uint256 end = middle + width;
                if (end > aliases.length) end = aliases.length;
                uint256 left = first;
                uint256 right = middle;
                for (uint256 output = first; output < end; ++output) {
                    if (
                        right == end
                            || (left < middle
                                && aliases[left].originalKey <= aliases[right].originalKey)
                    ) {
                        scratch[output] = aliases[left++];
                    } else {
                        scratch[output] = aliases[right++];
                    }
                }
            }
            (aliases, scratch) = (scratch, aliases);
        }
        return aliases;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import {
    StreamArtistRecoveredHydrationTypes as RH
} from "../../interfaces/stream/artist/StreamArtistRecoveredHydrationTypes.sol";
import {
    StreamArtistRecoveredHydrationProvenance as Provenance
} from "./StreamArtistRecoveredHydrationProvenance.sol";

/// @notice Owner-local immutable import prefix and precise origins for retained historical facts.
/// @dev A separate namespace; original owner fields, native rows, counters and roots are untouched.
/// Fixed import workers call these methods only after their original operation60 caller/snapshot
/// check and complete source authentication. This storage is not an alternative authorization API.
library StreamArtistRecoveredHydrationState {
    bytes32 private constant SLOT = keccak256("6529STREAM_ARTIST_RECOVERED_HYDRATION_STATE_V1");

    struct State {
        bytes32 commitment;
        bytes32 profile;
        RH.OriginEnvironment[] origins;
        RH.OwnerEra[] eras;
        mapping(bytes32 => uint256) originIndexPlusOne;
        RH.JournalEntry[] journal;
        RH.ReplayAlias[] aliases;
        mapping(bytes32 => uint256) aliasIndexPlusOne;
        mapping(bytes32 => RH.Point) artifacts;
        mapping(bytes32 => RH.Point) activeReplayPoints;
        uint64 importedAtRevision;
        uint8 ownerIndex;
    }

    function _state() private pure returns (State storage s) {
        bytes32 slot = SLOT;
        assembly ("memory-safe") { s.slot := slot }
    }

    function commitment() public view returns (bytes32) {
        return _state().commitment;
    }

    function importedAtRevision() public view returns (uint64) {
        return _state().importedAtRevision;
    }

    /// @dev Stores only this owner's slice. The Coordinator authenticates the joined seven-owner
    /// certificate; no owner reads another owner's mutable state or duplicates its journal.
    function installPrefix(
        RH.Provenance memory p,
        uint8 ownerIndex,
        bytes32 importCommitment,
        uint64 localImportRevision
    ) public {
        Provenance.validate(p);
        installOwnerPrefix(
            RH.ownerProvenance(p, ownerIndex), ownerIndex, importCommitment, localImportRevision
        );
    }

    /// @dev The destination receives only its authenticated slice, not seven copies of the
    /// global certificate. Validation here is structural and performs no source-owner calls.
    function installOwnerPrefix(
        RH.OwnerProvenance memory p,
        uint8 ownerIndex,
        bytes32 importCommitment,
        uint64 localImportRevision
    ) public {
        State storage s = _state();
        if (
            importCommitment == 0 || localImportRevision == 0 || s.commitment != 0
                || ownerIndex >= 7 || s.origins.length != 0 || s.eras.length != 0
                || s.journal.length != 0 || s.aliases.length != 0
        ) revert RH.InvalidRecoveredHydrationProvenance();
        Provenance.validateOwner(p, ownerIndex);
        s.commitment = importCommitment;
        s.profile = RH.PROFILE;
        s.importedAtRevision = localImportRevision;
        s.ownerIndex = ownerIndex;
        for (uint256 i; i < p.origins.length; ++i) {
            RH.OwnerEra memory era = p.eras[i];
            s.origins.push(p.origins[i]);
            s.eras.push(era);
            s.originIndexPlusOne[era.originHash] = i + 1;
        }
        for (uint256 i; i < p.journal.length; ++i) {
            s.journal.push(p.journal[i]);
        }
        for (uint256 i; i < p.aliases.length; ++i) {
            RH.ReplayAlias memory alias_ = p.aliases[i];
            s.aliases.push(alias_);
            s.aliasIndexPlusOne[alias_.originalKey] = i + 1;
        }
    }

    function importedPrefix() public view returns (RH.OwnerProvenance memory p) {
        State storage s = _state();
        p.origins = s.origins;
        p.eras = s.eras;
        p.journal = s.journal;
        p.aliases = s.aliases;
    }

    /// @notice Bounded read of one immutable, producer-authenticated imported occurrence.
    /// @dev Owner index/registry come from the caller's fixed binding. No prefix scan,
    /// native fallback, cross-owner mutable read, storage write or new state field.
    function importedReceiptAt(uint256 index, uint8 ownerIndex, address currentRegistry)
        public
        view
        returns (RH.JournalEntry memory entry, bytes32 importCommitment, uint64 localImportRevision)
    {
        State storage s = _state();
        if (index >= s.journal.length || currentRegistry == address(0)) {
            revert RH.InvalidRecoveredHydrationProvenance();
        }
        entry = s.journal[index];
        (, importCommitment, localImportRevision,) = originCertificateInline(
            entry.position.point.environmentHash, ownerIndex, currentRegistry
        );
        RH.OwnerEra storage era =
            s.eras[s.originIndexPlusOne[entry.position.point.environmentHash] - 1];
        if (
            entry.position.point.ownerIndex != ownerIndex || entry.receipt.operation == 0
                || entry.receipt.recordHash == 0 || entry.position.nativeIndex >= era.nativeCount
                || entry.position.point.ownerRevision <= era.lowerRevision
                || entry.position.point.ownerRevision > era.checkpoint.ownerState.revision
        ) revert RH.InvalidRecoveredHydrationProvenance();
    }

    /// @notice Compact read of a key installed only by the unchanged validated op60 producer.
    /// @dev Full original environment bytes remain available through environment(). No cache/write.
    function originCertificate(bytes32 hash, uint8 ownerIndex, address currentRegistry)
        public view returns (bytes32, bytes32, uint64, uint8)
    {
        return originCertificateInline(hash, ownerIndex, currentRegistry);
    }

    /// @dev Same immutable namespace/checks in a caller's existing fixed read frame.
    /// Retains the public method above while avoiding a second cold delegatecall for Owner reads.
    function originCertificateInline(bytes32 hash, uint8 ownerIndex, address currentRegistry)
        internal view returns (bytes32, bytes32, uint64, uint8)
    {
        State storage s = _state();
        uint256 plus = s.originIndexPlusOne[hash];
        if (
            hash == 0 || s.commitment == 0 || s.profile != RH.PROFILE
                || s.importedAtRevision == 0 || ownerIndex >= 7 || s.ownerIndex != ownerIndex
                || plus == 0 || plus > s.origins.length || plus > s.eras.length
                || s.eras[plus - 1].originHash != hash
                || s.origins[plus - 1].registry == currentRegistry
        ) revert RH.InvalidRecoveredHydrationProvenance();
        return (hash, s.commitment, s.importedAtRevision, s.ownerIndex);
    }

    /// @notice Raw imported-only facts for a fixed STATIC validator. No new authority or cache.
    /// @dev Invalid/missing array membership produces a zero stored origin. The fixed consumer
    /// must check the returned original profile, commitment, revision and owner index as well.
    /// The existing certificate method and its complete revert behavior remain unchanged.
    function originFactsInline(bytes32 hash, address currentRegistry)
        internal view returns (bytes32 storedHash, bytes32 commitment_, uint64 revision, uint8 ownerIndex, bytes32 profile)
    {
        State storage s = _state();
        uint256 plus = s.originIndexPlusOne[hash];
        if (plus != 0 && plus <= s.origins.length && plus <= s.eras.length
            && s.origins[plus - 1].registry != currentRegistry) {
            storedHash = s.eras[plus - 1].originHash;
        }
        return (storedHash, s.commitment, s.importedAtRevision, s.ownerIndex, s.profile);
    }

    function environment(bytes32 originHash) public view returns (RH.OriginEnvironment memory) {
        State storage s = _state();
        uint256 plus = s.originIndexPlusOne[originHash];
        if (plus == 0) revert RH.InvalidRecoveredHydrationProvenance();
        return s.origins[plus - 1];
    }

    function historicalAlias(bytes32 originalKey) public view returns (RH.ReplayAlias memory) {
        State storage s = _state();
        uint256 plus = s.aliasIndexPlusOne[originalKey];
        if (plus == 0) revert RH.InvalidRecoveredHydrationProvenance();
        return s.aliases[plus - 1];
    }

    /// @dev Called for every authenticated imported native/auxiliary semantic artifact. Kind
    /// separates original records, executions, preparations, continuations and occurrence scopes.
    function installArtifact(bytes32 kind, bytes32 key, RH.Point memory point) public {
        State storage s = _state();
        _importedPoint(s, point);
        if (kind == 0 || key == 0) revert RH.InvalidRecoveredHydrationProvenance();
        bytes32 id = keccak256(abi.encode(kind, key));
        RH.Point storage old = s.artifacts[id];
        if (old.environmentHash != 0 && keccak256(abi.encode(old)) != keccak256(abi.encode(point))) revert RH.InvalidRecoveredHydrationProvenance();
        s.artifacts[id] = point;
    }

    /// @notice Missing imported metadata is an error, never an implicit current-domain artifact.
    function artifact(bytes32 kind, bytes32 key) public view returns (RH.Point memory point) {
        point = _state().artifacts[keccak256(abi.encode(kind, key))];
        if (kind == 0 || key == 0 || point.environmentHash == 0) {
            revert RH.InvalidRecoveredHydrationProvenance();
        }
    }

    /// @dev Only a fixed typed owner adapter may supply actualRevision, after reading the
    /// matching producer record from its own state. A caller accepting a returned current point
    /// must also prove a local native occurrence or the original current-domain producer hash.
    /// A retained raw revision alone is not proof of local production, even above the boundary.
    function artifactPoint(
        bytes32 kind,
        bytes32 key,
        uint64 actualRevision,
        RH.Point memory current
    ) public view returns (RH.Point memory point) {
        State storage s = _state();
        if (
            kind == 0 || key == 0 || actualRevision == 0 || current.environmentHash == 0
                || current.ownerIndex >= 7 || current.ownerRevision != actualRevision
                || (s.commitment != 0 && current.ownerIndex != s.ownerIndex)
        ) revert RH.InvalidRecoveredHydrationProvenance();
        point = s.artifacts[keccak256(abi.encode(kind, key))];
        if (point.environmentHash != 0) {
            if (point.ownerIndex != current.ownerIndex || point.ownerRevision != actualRevision) {
                revert RH.InvalidRecoveredHydrationProvenance();
            }
            return point;
        }
        if (s.commitment != 0 && actualRevision <= s.importedAtRevision) {
            revert RH.InvalidRecoveredHydrationProvenance();
        }
        return current;
    }

    /// @dev Install after the ordinary guard worker's checkpoint notes. One-way cutover latches
    /// remain historical and are never installed as destination active guards by that worker.
    function installActiveReplayPoint(bytes32 currentKey, bytes32 sourceKey) public {
        State storage s = _state();
        uint256 plus = s.aliasIndexPlusOne[sourceKey];
        if (
            s.commitment == 0 || currentKey == 0 || plus == 0
                || s.activeReplayPoints[currentKey].environmentHash != 0
        ) revert RH.InvalidRecoveredHydrationProvenance();
        s.activeReplayPoints[currentKey] = s.aliases[plus - 1].admittedAt;
    }

    /// @dev The actual original Checkpoint.noteReplay hook invokes this for a real current write.
    /// Its cell now carries a local mutation revision, so an old imported point must not survive.
    function noteLocalReplay(bytes32 key) public {
        if (key == 0) revert RH.InvalidRecoveredHydrationProvenance();
        delete _state().activeReplayPoints[key];
    }

    /// @dev The fixed owner must supply its actual nonempty replay cell and current environment.
    /// An absent historical override means that actual cell was produced in this owner, not that
    /// arbitrary missing keys or supplied revisions establish admission.
    function activeReplayPoint(bytes32 key, uint64 actualRevision, RH.Point memory current)
        public
        view
        returns (RH.Point memory point)
    {
        if (
            key == 0 || actualRevision == 0 || current.environmentHash == 0
                || current.ownerIndex >= 7 || current.ownerRevision != actualRevision
        ) revert RH.InvalidRecoveredHydrationProvenance();
        point = _state().activeReplayPoints[key];
        if (point.environmentHash == 0) return current;
        if (point.ownerIndex != current.ownerIndex || point.ownerRevision != actualRevision) {
            revert RH.InvalidRecoveredHydrationProvenance();
        }
    }

    function _importedPoint(State storage s, RH.Point memory point) private view {
        uint256 plus = s.originIndexPlusOne[point.environmentHash];
        if (s.commitment == 0 || plus == 0 || point.ownerIndex != s.ownerIndex) {
            revert RH.InvalidRecoveredHydrationProvenance();
        }
        RH.OwnerEra storage era = s.eras[plus - 1];
        // Original local55/56 guards precede this owner's operation60. They are legitimate
        // auxiliary points; the import boundary is a lower bound only for native suffix rows.
        if (point.ownerRevision == 0 || point.ownerRevision > era.checkpoint.ownerState.revision) {
            revert RH.InvalidRecoveredHydrationProvenance();
        }
    }
}

