            );
        }
        for (uint256 i; i < b.estates.length; ++i) {
            rows[at++] = IH.ClosureRow(
                b.estates[i].request.recordHash,
                X.resolutions(r).closures[b.estates[i].request.recordHash]
            );
        }
        for (uint256 i; i < b.recoveries.length; ++i) {
            rows[at++] = IH.ClosureRow(
