                _occurrence(p, b.artistId, 42, r.terminal.recordHash);
            } else if (r.phase == 3) {
                ++completed;
                _occurrence(p, b.artistId, 43, r.terminal.recordHash);
            } else if (r.phase != 1 || r.terminal.recordHash != 0) {
                revert IH.InvalidRecoveredIdentity(r.notice.recordHash);
            }
        }
