            revert IH.InvalidRecoveredIdentity(b.artistId);
        }
        for (uint256 i; i < b.standingRecords.length; ++i) {
            _native(
                p,
                b.artistId,
                b.standingRecords[i].position,
                51,
                b.standingRecords[i].record.recordHash
            );
            if (i != 0) {
