        Native.validate(b, p);
        Delegations.validate(b, p);
        Causes.validate(b, p);
        Vestings.validate(b, p);
        Guardians.validate(b, p);
        Actions.validate(b, p);
        Closures.validate(b);
        Documents.validate(b);
        return keccak256(abi.encode(IH.SCHEMA, b));
