    }

    function _hashes(uint256 root) private pure returns (mapping(bytes32 => bytes32) storage s) {
        assembly ("memory-safe") { s.slot := root }
    }

    function _recovery(uint256 root) private pure returns (Recovery.State storage s) {
        assembly ("memory-safe") { s.slot := root }
    }
}

