/// @notice Fixed shared original/record-history validation body; all full typed inputs are retained.
library StreamArtistRecoveredPlatformDisputeRowsKernel {
    function validate(
        D.Bundle memory b,
        AH.Query memory q,
        RH.OwnerProvenance memory p,
