pragma solidity ^0.8.19;
import { StreamArtistRecoveredPlatformTypes as P } from "./StreamArtistRecoveredPlatformTypes.sol";
import {
    StreamArtistRecoveredPlatformPayload as Payload
} from "./StreamArtistRecoveredPlatformPayload.sol";
import {
    StreamArtistRecoveredPlatformTransitionProof as Transition
} from "./StreamArtistRecoveredPlatformTransitionProof.sol";
import {
    StreamArtistPlatformTypes as PW
} from "../../interfaces/stream/artist/StreamArtistPlatformTypes.sol";
import {
    StreamArtistAttributionClaimTypes as AC
} from "../../interfaces/stream/artist/IStreamArtistAttributionClaims.sol";
import {
    StreamArtistRecoveredHydrationTypes as RH
} from "../../interfaces/stream/artist/StreamArtistRecoveredHydrationTypes.sol";
import {
    StreamArtistRecoveredSanctionHistoryTypes as H
} from "./StreamArtistRecoveredSanctionHistoryTypes.sol";
import {
    StreamArtistRecoveredDisputeHistoryTypes as D
} from "./StreamArtistRecoveredDisputeHistoryTypes.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";

/// @notice Authenticated original Archive payloads bind all original Platform record fields.
library StreamArtistRecoveredPlatformNativeProof {
    function advance(
        P.Platform memory b,
        PW.State memory current,
        RH.OwnerProvenance memory p,
        uint256 era,
        H.Envelope memory e
    ) public pure returns (PW.State memory) {
        return _advance(b, current, p, era, e, false);
    }

    function advanceWithRecords(
        P.Platform memory b,
        PW.State memory current,
        RH.OwnerProvenance memory p,
        uint256 era,
        H.Envelope memory e
    ) public pure returns (PW.State memory) {
        return _advance(b, current, p, era, e, true);
    }

    function _advance(
        P.Platform memory b,
        PW.State memory current,
        RH.OwnerProvenance memory p,
        uint256 era,
        H.Envelope memory e,
        bool includeRecords
    ) private pure returns (PW.State memory) {
        RH.OriginEnvironment memory o = p.origins[era];
        RH.Point memory point = RH.Point(p.eras[era].originHash, 4, e.after_[4].revision);
        bytes32 scope;
        bytes32 action = e.value;
        bytes32 state;
        bytes32 primary = e.operation == 11 ? bytes32(0) : e.value;
        if (e.operation == 8) {
            (uint256 id, bytes32 statement, bytes32 role, uint64 revision) =
                abi.decode(e.payload, (uint256, bytes32, bytes32, uint64));
            if (
                keccak256(e.payload) != keccak256(abi.encode(id, statement, role, revision))
                    || id != b.collectionId || statement != b.state.declaration.statementHash
                    || e.actor != b.state.declaration.actor
                    || e.value != b.state.declaration.recordHash
                    || !D.samePoint(point, b.declarationPoint)
                    || current.declaration.recordHash != 0
            ) {
                _invalid();
            }
            current.declaration = b.state.declaration;
            scope = bytes32(id);
        } else if (e.operation == 9 || e.operation == 10) {
            Payload.Claim memory c = Payload.claim(e.payload);
            _documents(
                b.collectionId, c.evidence, c.reason, 0, c.evidenceDocument, c.reasonDocument
            );
            if (c.id != b.collectionId || bytes(c.uri).length > 4096) _invalid();
            scope = keccak256(abi.encode(c.id, e.actor, c.evidence, c.reason));
            if (e.operation == 9) {
                PW.Claim memory r = _claim(b, point);
                if (
                    r.recordHash != e.value || r.claimant != e.actor || r.evidenceHash != c.evidence
                        || r.reasonHash != c.reason
                        || r.proposedArtist != c.evidenceDocument.proposedArtist
                ) _invalid();
                ++current.claimCount;
                current.latestClaim = r.recordHash;
            } else {
                AC.Claim memory r = _allegation(b, point);
                if (
                    r.recordHash != e.value || r.claimant != e.actor || r.evidenceHash != c.evidence
                        || r.reasonHash != c.reason
                        || r.proposedArtist != c.evidenceDocument.proposedArtist
                        || keccak256(bytes(r.reasonURI)) != keccak256(bytes(c.uri))
                ) _invalid();
                state = keccak256(abi.encode(r));
                action = keccak256(
                    abi.encode(
                        c.id,
                        e.actor,
                        c.evidence,
                        c.reason,
                        c.uri,
                        c.evidenceDocument.proposedArtist
                    )
                );
            }
        } else if (e.operation == 11 || e.operation == 53) {
            Payload.ContestPayload memory c = Payload.contest(e.payload);
            bool correction = e.operation == 53;
            _documents(
                b.collectionId, c.evidence, c.reason, c.claim, c.evidenceDocument, c.reasonDocument
            );
            PW.Context memory expected;
            expected.scopeHash = keccak256(
                abi.encode(
                    keccak256("6529STREAM_PLATFORM_WORKS_GOVERNANCE_SCOPE_V1"),
                    o.chainId,
                    o.registry,
                    o.core,
                    b.collectionId,
                    correction
                )
            );
            expected.oldValueHash = keccak256(
                abi.encode(
                    current.declaration,
                    current.contestState,
                    current.contestClaim,
                    current.contestRecord,
                    current.correction
                )
            );
            expected.newValueHash = keccak256(
                abi.encode(
                    expected.scopeHash,
                    expected.oldValueHash,
                    c.state,
                    c.claim,
                    c.evidence,
                    c.reason
                )
            );
            if (
                c.id != b.collectionId || c.correction != correction || (correction && c.state != 3)
                    || keccak256(abi.encode(c.context)) != keccak256(abi.encode(expected))
                    || c.governance.scopeHash != expected.scopeHash
                    || c.governance.oldValueHash != expected.oldValueHash
                    || c.governance.newValueHash != expected.newValueHash
                    || c.governance.actionId == 0 || c.governance.proposer == address(0)
                    || c.governance.roleMutationHash == 0 || c.governance.roleRevision == 0
                    || c.governance.actionClass != (correction ? 2 : 1)
            ) _invalid();
            scope = keccak256(abi.encode(b.collectionId, c.governance.actionId));
            if (correction) {
                PW.Correction memory r = b.state.correction;
                if (
                    !D.samePoint(point, b.correctionPoint) || r.recordHash != e.value
                        || r.claimRecordHash != c.claim || r.evidenceHash != c.evidence
                        || r.reasonHash != c.reason || r.approvalActionId != c.governance.actionId
                        || r.proposedArtist != c.evidenceDocument.proposedArtist
                        || current.correction.recordHash != 0
                ) _invalid();
                current.correction = PW.Correction(
                    r.collectionId,
                    r.proposedArtist,
                    r.claimRecordHash,
                    r.sustainedContestRecordHash,
                    r.evidenceHash,
                    r.reasonHash,
                    r.approvalActionId,
                    r.approvedAt,
                    0,
                    false,
                    r.recordHash
                );
            } else {
                PW.Contest memory r = _contest(b, point);
                if (
                    r.recordHash != e.value || r.state != c.state || r.claimRecordHash != c.claim
                        || r.evidenceHash != c.evidence || r.reasonHash != c.reason
                        || r.actionId != c.governance.actionId
                        || r.adjudicatedArtist != c.evidenceDocument.proposedArtist
                ) _invalid();
                current.contestState = r.state;
                current.contestClaim = r.claimRecordHash;
                current.contestRecord = r.recordHash;
            }
        } else {
            _invalid();
        }
        if (e.operation != 10) state = keccak256(abi.encode(b.collectionId, current));
        _otherSnapshots(e);
        if (includeRecords) {
            Transition.validateWithRecords(
                o,
                p,
                era,
                e,
                action,
                state,
                Transition.replay(o, e.operation, scope, e.value),
                primary
            );
        } else {
            Transition.validate(
                o,
                p,
                era,
                e,
                action,
                state,
                Transition.replay(o, e.operation, scope, e.value),
                primary
            );
        }
        return current;
    }

    function _documents(
        uint256 id,
        bytes32 evidence,
        bytes32 reason,
        bytes32 claim,
        PW.Evidence memory a,
        PW.Evidence memory b
    ) private pure {
        if (
            evidence == 0 || reason == 0 || a.schemaVersion != 1 || b.schemaVersion != 1
                || a.collectionId != id || b.collectionId != id || a.narrativeHash == 0
                || b.narrativeHash == 0 || a.claimRecordHash != claim || b.claimRecordHash != claim
                || a.proposedArtist != b.proposedArtist || keccak256(abi.encode(a)) != evidence
                || keccak256(abi.encode(b)) != reason
        ) _invalid();
    }

    function _claim(P.Platform memory b, RH.Point memory point)
        private
        pure
        returns (PW.Claim memory)
    {
        for (uint256 i; i < b.claims.length; ++i) {
            if (D.samePoint(point, b.claims[i].point)) return b.claims[i].record;
        }
        _invalid();
    }

    function _allegation(P.Platform memory b, RH.Point memory point)
        private
        pure
        returns (AC.Claim memory)
    {
        for (uint256 i; i < b.allegations.length; ++i) {
            if (D.samePoint(point, b.allegations[i].point)) return b.allegations[i].record;
        }
        _invalid();
    }

    function _contest(P.Platform memory b, RH.Point memory point)
        private
        pure
        returns (PW.Contest memory)
    {
        for (uint256 i; i < b.contests.length; ++i) {
            if (D.samePoint(point, b.contests[i].point)) return b.contests[i].record;
        }
        _invalid();
    }

    function _otherSnapshots(H.Envelope memory e) private pure {
        T.Snapshot memory zero;
        for (uint8 i; i < 7; ++i) {
            if (i == 4) continue;
            if (e.operation == 8 && (i == 0 || i == 6)) {
                if (
                    e.before_[i].domainId != RH.ownerDomain(i) || e.before_[i].stateRoot == 0
                        || e.before_[i].recordChainTip == 0
                        || keccak256(abi.encode(e.before_[i])) != keccak256(abi.encode(e.after_[i]))
                ) {
                    _invalid();
                }
            } else if (
                keccak256(abi.encode(e.before_[i])) != keccak256(abi.encode(zero))
                    || keccak256(abi.encode(e.after_[i])) != keccak256(abi.encode(zero))
            ) {
                _invalid();
            }
        }
    }

    function _invalid() private pure {
        revert RH.InvalidRecoveredHydrationProfile();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import { StreamArtistRecoveredPlatformTypes as P } from "./StreamArtistRecoveredPlatformTypes.sol";
import {
    StreamArtistPlatformTypes as PW
} from "../../interfaces/stream/artist/StreamArtistPlatformTypes.sol";
import {
    StreamArtistAttributionClaimTypes as AC
} from "../../interfaces/stream/artist/IStreamArtistAttributionClaims.sol";
import {
    StreamArtistRecoveredDisputeHistoryTypes as D
} from "./StreamArtistRecoveredDisputeHistoryTypes.sol";
import {
    StreamArtistRecoveredAcceptedGenerationTypes as A
} from "./StreamArtistRecoveredAcceptedGenerationTypes.sol";
import {
    StreamArtistRecoveredHydrationTypes as RH
} from "../../interfaces/stream/artist/StreamArtistRecoveredHydrationTypes.sol";
import {
    StreamArtistRecoveredHydrationChronology as Clock
} from "./StreamArtistRecoveredHydrationChronology.sol";

/// @notice Original collection-only native records, exact source domains and all replay subjects.
/// @dev The separate Archive timeline proves fields outside record hashes and op1/op2 mutations.
library StreamArtistRecoveredPlatformNativeRows {
    struct Cursor {
        PW.State state;
        uint256 claims;
        uint256 contests;
        uint256 allegations;
        bytes32 allegation;
        bytes32 display;
    }

    function validate(P.Platform memory b, RH.OwnerProvenance memory p)
        public
        pure
        returns (D.Guard[] memory guards)
    {
        if (
            b.collectionId == 0 || b.provenance != RH.ownerProvenanceHash(p, 4)
                || P.nativeCount(b) == 0 || P.nativeCount(b) > RH.MAX_JOURNAL_ENTRIES
        ) _invalid();
        guards = new D.Guard[](P.nativeCount(b));
        uint256 n;
        Cursor memory c;
        for (uint256 i; i < p.journal.length; ++i) {
            RH.JournalEntry memory j = p.journal[i];
            uint16 op = j.receipt.operation;
            if (!P.nativeOperation(op)) continue;
            if (
                j.receipt.artistId != 0 || j.receipt.collectionId != b.collectionId
                    || n == guards.length
            ) _invalid();
            Clock.validateOwnerPoint(p, 4, j.position.point);
            RH.OriginEnvironment memory o = p.origins[A.era(p, j.position.point.environmentHash)];
            bytes32 scope;
            if (op == 8) scope = _declare(b, j, o, c);
            else if (op == 9) scope = _claim(b, j, o, c);
            else if (op == 10) scope = _allegation(b, j, o, c);
            else if (op == 11) scope = _contest(b, j, o, c);
            else scope = _correction(b, j, o, c);
            bytes32 surface = op == 10
                ? keccak256("attribution_lifecycle.replay.claim_record_hash_uniqueness")
                : keccak256(abi.encode("PLATFORM_WORKS", op));
            guards[n++] = D.Guard(surface, scope, j.receipt.recordHash, j.position.point);
        }
        // Copy before clearing the two lifecycle fields: no mutation of the retained Bundle.
        PW.State memory expected = abi.decode(abi.encode(b.state), (PW.State));
        expected.correction.correctiveGeneration = 0;
        expected.correction.accepted = false;
        if (
            n != guards.length || c.claims != b.claims.length || c.contests != b.contests.length
                || c.allegations != b.allegations.length || c.allegations != b.allegationCount
                || c.allegation != b.latestAllegation || c.display != b.latestDisplayClaim
                || keccak256(abi.encode(c.state)) != keccak256(abi.encode(expected))
        ) _invalid();
        for (uint256 i; i < guards.length; ++i) {
            for (uint256 k; k < i; ++k) {
                if (guards[i].surface == guards[k].surface && guards[i].scope == guards[k].scope) {
                    _invalid();
                }
            }
        }
        // Contest and correction use one shared original governance-action cell.
        for (uint256 i; i < b.contests.length; ++i) {
            bytes32 action = b.contests[i].record.actionId;
            if (action == b.state.correction.approvalActionId) _invalid();
            for (uint256 k; k < i; ++k) {
                if (b.contests[k].record.actionId == action) _invalid();
            }
        }
    }

    function validateWithRecords(P.Platform memory b, RH.OwnerProvenance memory p)
        public
        pure
        returns (D.Guard[] memory guards)
    {
        if (P.nativeCount(b) != 0) return validate(b, p);
        P.Platform memory empty;
        // Archive catalogues/operations are still required by the independent binding timeline.
        empty.provenance = RH.ownerProvenanceHash(p, 4);
        empty.collectionId = b.collectionId;
        empty.catalogues = b.catalogues;
        empty.operations = b.operations;
        if (b.collectionId == 0 || keccak256(abi.encode(b)) != keccak256(abi.encode(empty))) {
            _invalid();
        }
        return new D.Guard[](0);
    }

    function _declare(
        P.Platform memory b,
        RH.JournalEntry memory j,
        RH.OriginEnvironment memory o,
        Cursor memory c
    ) private pure returns (bytes32) {
        PW.Declaration memory r = b.state.declaration;
        if (
            c.state.declaration.recordHash != 0 || r.recordHash == 0 || r.statementHash == 0
                || r.actor == address(0) || !D.samePoint(b.declarationPoint, j.position.point)
                || j.receipt.recordHash != r.recordHash
                || r.recordHash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_PLATFORM_WORKS_DECLARATION_V1"),
                            o.chainId,
                            o.registry,
                            o.core,
                            b.collectionId,
                            r.statementHash,
                            r.declaredAt
                        )
                    )
        ) _invalid();
        c.state.declaration = r;
        return bytes32(b.collectionId);
    }

    function _claim(
        P.Platform memory b,
        RH.JournalEntry memory j,
        RH.OriginEnvironment memory o,
        Cursor memory c
    ) private pure returns (bytes32 scope) {
        if (c.claims == b.claims.length) _invalid();
        P.ClaimRow memory row = b.claims[c.claims++];
        PW.Claim memory r = row.record;
        if (
            c.state.declaration.recordHash == 0 || r.collectionId != b.collectionId
                || r.claimant == address(0) || r.evidenceHash == 0 || r.reasonHash == 0
                || !D.samePoint(row.point, j.position.point) || r.recordHash != j.receipt.recordHash
                || r.recordHash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_PLATFORM_WORKS_CLAIM_RECORD_V1"),
                            o.chainId,
                            o.registry,
                            o.core,
                            b.collectionId,
                            r.claimant,
                            r.evidenceHash,
                            r.reasonHash,
                            r.filedAt
                        )
                    )
        ) _invalid();
        ++c.state.claimCount;
        c.state.latestClaim = r.recordHash;
        c.display = r.recordHash;
        return keccak256(abi.encode(b.collectionId, r.claimant, r.evidenceHash, r.reasonHash));
    }

    function _allegation(
        P.Platform memory b,
        RH.JournalEntry memory j,
        RH.OriginEnvironment memory o,
        Cursor memory c
    ) private pure returns (bytes32 scope) {
        if (c.allegations == b.allegations.length) _invalid();
        P.AttributionClaimRow memory row = b.allegations[c.allegations++];
        AC.Claim memory r = row.record;
        if (
            r.collectionId != b.collectionId || r.claimant == address(0) || r.evidenceHash == 0
                || r.reasonHash == 0 || r.filedAt == 0 || bytes(r.reasonURI).length > 4096
                || r.index != c.allegations || r.previousRecordHash != c.allegation
                || !D.samePoint(row.point, j.position.point) || r.recordHash != j.receipt.recordHash
                || r.recordHash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_ARTIST_ATTRIBUTION_CLAIM_RECORD_V1"),
                            o.chainId,
                            o.registry,
                            o.core,
                            b.collectionId,
                            r.claimant,
                            r.evidenceHash,
                            r.reasonHash,
                            r.filedAt
                        )
                    )
        ) _invalid();
        c.allegation = r.recordHash;
        c.display = r.recordHash;
        return keccak256(abi.encode(b.collectionId, r.claimant, r.evidenceHash, r.reasonHash));
    }

    function _contest(
        P.Platform memory b,
        RH.JournalEntry memory j,
        RH.OriginEnvironment memory o,
        Cursor memory c
    ) private pure returns (bytes32 scope) {
        if (c.contests == b.contests.length) _invalid();
        P.ContestRow memory row = b.contests[c.contests++];
        PW.Contest memory r = row.record;
        if (
            c.state.declaration.recordHash == 0 || r.collectionId != b.collectionId
                || r.evidenceHash == 0 || r.reasonHash == 0 || r.actionId == 0
                || r.previousRecordHash != c.state.contestRecord
                || !D.samePoint(row.point, j.position.point) || r.recordHash != j.receipt.recordHash
                || (r.state == 1
                        ? (c.state.contestState != 0 && c.state.contestState != 2)
                        : ((r.state != 2 && r.state != 3)
                            || c.state.contestState != 1
                            || c.state.contestClaim != r.claimRecordHash))
        ) _invalid();
        bool found;
        for (uint256 k; k < c.claims; ++k) {
            if (b.claims[k].record.recordHash == r.claimRecordHash) found = true;
        }
        if (
            !found
                || r.recordHash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_PLATFORM_WORKS_CONTEST_TRANSITION_V1"),
                            o.chainId,
                            o.owners[4],
                            PW.Contest(
                                r.collectionId,
                                r.adjudicatedArtist,
                                r.state,
                                r.claimRecordHash,
                                r.evidenceHash,
                                r.reasonHash,
                                r.actionId,
                                r.previousRecordHash,
                                r.changedAt,
                                0
                            )
                        )
                    )
        ) {
            _invalid();
        }
        c.state.contestState = r.state;
        c.state.contestClaim = r.claimRecordHash;
        c.state.contestRecord = r.recordHash;
        return keccak256(abi.encode(b.collectionId, r.actionId));
    }

    function _correction(
        P.Platform memory b,
        RH.JournalEntry memory j,
        RH.OriginEnvironment memory o,
        Cursor memory c
    ) private pure returns (bytes32 scope) {
        PW.Correction memory r = b.state.correction;
        if (
            c.state.correction.recordHash != 0 || c.state.contestState != 3 || c.contests == 0
                || r.collectionId != b.collectionId || r.claimRecordHash != c.state.contestClaim
                || r.sustainedContestRecordHash != c.state.contestRecord
                || r.proposedArtist == address(0)
                || r.proposedArtist != b.contests[c.contests - 1].record.adjudicatedArtist
                || r.evidenceHash == 0 || r.reasonHash == 0 || r.approvalActionId == 0
                || !D.samePoint(b.correctionPoint, j.position.point)
                || r.recordHash != j.receipt.recordHash
                || r.recordHash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_PLATFORM_WORKS_CORRECTION_RECORD_V1"),
                            o.chainId,
                            o.registry,
                            o.core,
                            b.collectionId,
                            r.sustainedContestRecordHash,
                            r.claimRecordHash,
                            r.evidenceHash,
                            r.reasonHash,
                            r.approvalActionId,
                            r.approvedAt
                        )
                    )
        ) {
            _invalid();
        }
        c.state.correction = PW.Correction(
            r.collectionId,
            r.proposedArtist,
            r.claimRecordHash,
