            return Acceptance.encode(
                Acceptance.collect(source.owners[3], q, RH.ownerProvenance(p, 3), b.bindings),
                q,
                RH.ownerProvenance(p, 3)
            );
        }
        if (ownerIndex == 4) return collected;
        _invalid();
    }

