        P.Evidence memory v0 = _original_requireRecordPublication(
            Context(host, coordinator), recordHash, publication
        );
        return abi.encode(v0);
    }

    function _original_requireRecordPublication(
        Context memory x,
        bytes32 recordHash,
        P.Publication memory publication
