    bytes32 internal constant APPEAL = keccak256("ROLE_ATTRIBUTION_APPEAL");

    struct Finding {
        bytes32 guardianRecordHash;
        address[] parties;
    }

    struct Document {
        bytes32 requestCommitment;
        bytes32 causeHash;
