            abi.encode(
                keccak256("6529STREAM_ARTIST_GUARDIAN_APPEAL_REQUEST_V1"),
                uint16(1),
                request.artistId,
                request.newAddress,
                request.vestedAuthorityClass,
                request.expectedCauseHash,
                request.expectedResolutionHash,
                bytes32(0),
                request.reasonHash,
                request.supersededRecordHashes
            )
        );
    }

