        uint256 chainId,
        address registry,
        address owner,
        Document memory document
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_HOSTILE_GUARDIAN_EVIDENCE_V1"),
                uint16(1),
