        // memory and returns it as runtime code.
        //   0x600B  PUSH1 0x0B   (preamble length)
        //   0x59    MSIZE        (0)
        //   0x81    DUP2
        //   0x38    CODESIZE
        //   0x03    SUB          (runtime length)
        //   0x80    DUP1
        //   0x92    SWAP3
        //   0x59    MSIZE        (0)
        //   0x39    CODECOPY
        //   0xF3    RETURN
